comms.text:
@1 וּמַלֵיל יְיָ עִם מֹשֶׁה בָּתַר דְמִיתוּ תְּרֵין בְּנֵי אַהֲרֹן בְּקָרוֹבֵיהוֹן אֶשָׁתָא נוּכְרֵיתָא קֳדָם יְיָ וּמִיתוּ:
@2 וַאֲמַר יְיָ לְמֹשֶׁה מַלֵל עִם אַהֲרֹן אָחוּךְ וְלָא יְהֵי עָלֵל בְּכָל עִדָן לְקוּדְשָׁא מִגָיו לְפָרֻכְתָּא לָקֳדָם כַּפֻּרְתָּא דִי עַל אֲרוֹנָא וְלָא יְמוּת אֲרֵי בַּעֲנָנָא אֲנָא מִתְגְלִי עַל בֵּית כַּפֻּרְתָּא:
@3 בְּדָא יְהֵי עָלֵל אַהֲרֹן לְקוּדְשָׁא בְּתוֹר בַּר תּוֹרֵי לְחַטָּאתָא וּדְכַר לַעֲלָתָא:
@4 כִּתּוּנָא דְבוּצָא קוּדְשָׁא יִלְבָּשׁ וּמִכְנְסִין דְבוּץ יְהוֹן עַל בִּסְרֵהּ וּבְהֶמְיָנָא דְבוּץ יֵסַר וּבְמִצְנֶפְתָּא דְבוּצָא יָחֵת בְּרֵישֵׁהּ לְבוּשֵׁי קוּדְשָׁא אִנוּן וְיַסְחֵי בְמַיָא יָת בִּ:סרֵהּ וְיַלְבְּשִׁנוּן:
@5 וּמִן כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל יִסַב תְּרֵין צְפִירֵי עִזִין לְחַטָאתָא וּדְכַר חַד לַעֲלָתָא:
@6 וִיקָרֵב אַהֲרֹן יָת תּוֹרָא דְחַטָּאתָא דִי לֵהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵהּ:
@7 וְיִסַב יָת תְּרֵין צְפִירִין וִיקִים יָתְהוֹן קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:
@8 וְיִתֵּן אַהֲרֹן עַל תְּרֵין צְפִירִין עַדְבִין עַדְבָא חַד לִשְׁמָא דַיְיָ וְעַדְבָא חַד לַעֲזָאזֵל:
@9 וִיקָרֵב אַהֲרֹן יָת צְפִירָא דִי סְלִיק עֲלוֹהִי עַדְבָא לִשְׁמָא דַיְיָ וְיַעְבְּדִנֵהּ חַטָאתָא:
@10 וּצְפִירָא דִי סְלִיק עֲלוֹהִי עַדְבָא לַעֲזָאזֵל יִתָּקַם כַּד חַי קֳדָם יְיָ לְכַפָּרָא עֲלוֹהִי לְשַׁלַח יָתֵהּ לַעֲזָאזֵל לְמַדְבְּרָא:
@11 וִיקָרֵב אַהֲרֹן יָת תּוֹרָא דְחַטָאתָא דִי לֵהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵהּ וְיִכּוֹס יָת תּוֹרָא דְחַטָאתָא דִי לֵהּ:
@12 וְיִסַב מְלֵי מַחְתִּיתָא גוּמְרִין דְאֶשָׁא מֵעִלַוֵי מַדְבְּחָא מִן קֳדָם יְיָ וּמְלֵי חָפְנוֹהִי קְטוֹרֶת בּוּסְמִין דַקִיקִין וְיָעֵל מִגָיו לְפָרֻכְתָּא:
@13 וְיִתֵּן יָת קְטוֹרֶת בּוּסְמַיָא עַל אֶשָׁתָא לָקֳדָם יְיָ וְחָפֵי עֲנָנָא קְטָרְתָּא יָת כַּפֻּרְתָּא דִי עַל סַהֲדוּתָא וְלָא יְמוּת:
@14 וְיִסַב מִדְמָא דְתוֹרָא וְיַדֵי בְאֶצְבְּעֵהּ עַל אַפֵּי כַּפּוּרְתָּא קִדוּמָא וְלָקֳדָם כַּפֻּרְתָּא יַדִי שְׁבַע זִמְנִין מִן דְמָא בְּאֶצְבְּעֵהּ:
@15 וְיִכּוֹס יָת צְפִירָא דְחַטָאתָא דִי לְעַמָא וְיָעֵל יָת דְמֵהּ לְמִגָיו לְפָרֻכְתָּא וְיַעְבֵּד לִדְמֵהּ כְּמָא דִי עֲבַּד לִדְמָא דְתוֹרָא וְיַדִי יָתֵהּ עַל כַּפֻּרְתָּא וְלָקֳדָם כַּפֻּרְתָּא:
@16 וִיכַפֵּר עַל קוּדְשָׁא מִסוֹאֲבַת בְּנֵי יִשְׂרָאֵל וּמִמֶרְדֵיהוֹן לְכָל חֲטָאֵיהוֹן וְכֵן יַעְבֵּד לְמַשְׁכַּן זִמְנָא דְשָׁרֵי עִמְהוֹן בְּגוֹ סוֹאֲבָתְהוֹן:
@17 וְכָל אֱנַשׁ לָא יְהֵי בְּמַשְׁכַּן זִמְנָא בְּמֵעֲלֵהּ לְכַפָּרָא בְקוּדְשָׁא עַד מִפְּקֵהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵהּ וְעַל כָּל קְהָלָא דְיִשְׂרָאֵל:
@18 וְיִפּוֹק לְמַדְבְּחָא דִי קֳדָם יְיָ וִיכַפֵּר עֲלוֹהִי וְיִסַב מִדְמָא דְתוֹרָא וּמִדְמָא דִצְפִירָא וְיִתֵּן עַל קַרְנַת מַדְבְּחָא סְחוֹר סְחוֹר:
@19 וְיַדֵי עֲלוֹהִי מִן דְמָא בְּאֶצְבְּעֵהּ שְׁבַע זִמְנִין וִידַכִּנֵהּ וִיקַדְשִׁנֵהּ מִסוֹאֲבַת בְּנֵי יִשְׂרָאֵל:
@20 וִישֵׁיצֵי מִלְכַפָּרָא עַל קוּדְשָׁא וְעַל מַשְׁכַּן זִמְנָא וְעַל מַדְבְּחָא וִיקָרֵב יָת צְפִירָא חַיָא:
@21 וְיִסְמוֹךְ אַהֲרֹן יָת תַּרְתֵּין יְדוֹהִי עַל רֵישׁ צְפִירָא חַיָא וִיוַדֵי עֲלוֹהִי יָת כָּל עֲוָיַת בְּנֵי יִשְׂרָאֵל וְיָת כָל מֶרְדֵיהוֹן לְכָל חֲטָּאֵיהוֹן וְיִתֵּן יָתְהוֹן עַל רֵישׁ צְפִירָא וִישַׁלַח בְּיַד גְבַר דִזְמִין לִמְהַךְ לְמַדְבְּרָא:
@22 וְיִטוֹל צְפִירָא עֲלוֹהִי יָת כָּל חוֹבֵיהוֹן לְאַרְעָא דְלָא יָתְבָא וִישַׁלַח יַת צְפִירָא בְּמַדְבְּרָא:
@23 וְיֵיעוֹל אַהֲרֹן לְמַשְׁכַּן זִמְנָא וְיַשְׁלַח יָת לְבוּשֵׁי בוּצָא דִי לְבַשׁ בְּמֵעֲלֵהּ לְקוּדְשָׁא וְיַצְנִעוּן תַּמָן:
@24 וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא בַּאֲתַר קַדִישׁ וְיִלְבַּשׁ יָת לְבוּשׁוֹהִי וְיִפּוֹק וְיַעְבֵּד יָת עֲלָתֵהּ וְיָת עֲלַת עַמָא וִיכַפַּר עֲלוֹהִי וְעַל עַמָּא:
@25 וְיָת תַּרְבָּא דְחַטָאתָא יַסֵק לְמַדְבְּחָא:
@26 וּדְמוֹבִיל יָת צְפִירָא לַעֲזָאזֵל יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא וּבָתַר כֵּן יֵיעוֹל לְמַשְׁרִיתָא:
@27 וְיָת תּוֹרָא דְחַטָאתָא וְיָת צְפִירָא דְחַטָאתָא דִי אִתָּעַל מִדִמְהוֹן לְכַפָּרָא בְקוּדְשָׁא יִתַּפְּקוּן לְמִבָּרָא לְמַשְּׁרִיתָא וְיוֹקְדוּן בְּנוּרָא יָת מַשְׁכֵּיהוֹן וְיָת בִּסְרְהוֹן וְיָת אָכְלֵיהוֹן:
@28 וּדְמוֹקִיד יָתְהוֹן יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא וּבָתַר כֵּן יֵיעוֹל למַשְׁרִיתָא:
@29 וּתְהֵי:לְכוֹן לִקְיַם עָלָם בְּיַרְחָא שְׁבִיעָאָה בְּעַשְׂרָא לְיַרְחָא תְּעַנוּן יָת נַפְשָׁתֵיכוֹן וְכָל עִבִידָא לָא תַעְבְּדוּן יַצִיבָא וְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן:
@30 אֲרֵי בְיוֹמָא הָדֵין יְכַפֵּר עֲלֵיכוֹן לְדַכָּאָה יָתְכוֹן מִכָּל חוֹבֵיכוֹן קֳדָם יְיָ תִּדְכּוּן:
@31 שְׁבַת שְׁבָתָא הִיא לְכוֹן וּתְעַנוּן יָת נַפְשָּׁתֵיכוֹן קְיַם עֲלָם:
@32 וִיכַפֵּר כַּהֲנָא דִי רַבִּי יָתֵהּ וְדִי יְקָרֵב יָת קֻרְבָּנֵהּ לְשַׁמָשָׁא תְּחוֹת אֲבוּהִי וְיִלְבַּשׁ יָת לְבוּשֵׁי בוּצָא:לבוּשֵׁי קוּדְשָׁא:
@33 וִיכַפֵּר עַל מִקְדַשׁ קוּדְשָׁא וְעַל מַשְׁכַּן זִמְנָא וְעַל מַדְבְּחָא יְכַפַּר וְעַל כַּהֲנַיָא וְעַל כָּל עַמָא דִקְהָלָא יְכַפַּר:
@34 וּתְהֵי דָא לְכוֹן לִקְיַם עָלָם לְכַפָּרָא עַל בְּנֵי יִשְׂרָאֵל מִכָּל חוֹבֵיהוֹן חֲדָא בְּשַׁתָּא וַעֲבַד כְּמָא דִי פַּקִיד יְיָ יָת מֹשֶׁה:
@35 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@36 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן דֵין פִּתְגָמָא דִי פַקִיד יְיָ לְמֵימָר:
@37 גְבַר גְבַר מִבֵּית יִשְׂרָאֵל דִי יִכּוֹס תּוֹר אוֹ אִמַר אוֹ עִזָא בְּמַשְׁרִיתָא אוֹ דִי יִכּוֹס מִבָּרָא לְמַשְׁרִיתָא:
@38 וְלִתְרַע מַשְׁכַּן זִמְנָא לָא אַיְתֵהּ לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ קֳדָם מַשְׁכְּנָא דַיְיָ דְמָא יִתְחַשַׁב לְגַבְרָא הַהוּא דְמָא אֲשַׁד וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מִגוֹ עַמֵהּ:
@39 בְּדִיל דִי יַיְתוּן בְּנֵי יִשְׂרָאֵל יָת דִבְחֵיהוֹן דִי אִנוּן דָבְחִין עַל אַפֵּי חַקְלָא וְיַיְתוּנוּן לָקֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא לְוָת כַּהֲנָא וְיִכְסוּן נִכְסַת קוּדְשִׁין קֳדָם יְיָ יָתְהוֹן:
@40 וְיִזְרוֹק כַּהֲנָא יָת דְמָא עַל מַדְבְּחָא דַיְיָ בִּתְרַע מַשְׁכַּן זִמְנָא וְיַסֵק תַּרְבָּא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:
@41 וְלָא יִדְבְּחוּן עוֹד יָת דִבְחֵיהוֹן לַשֵׁדִין דִי אִנוּן טָעָן בַּתְרֵיהוֹן קְיַם עָלָם תְּהֵי דָא לְהוֹן לְדָרֵיהוֹן:
@42 וּלְהוֹן תֵּימַר גְבַר גְבַר מִבֵּית יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן דִי יַסֵק עֲלָתָא אוֹ נִכְסַת קוּדְשַׁיָא:
@43 וְלִתְרַע מַשְׁכַּן זִמְנָא לָא אַיְתִנֵהּ לְמֶעְבַּד יָתֵהּ קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מֵעַמֵהּ:
@44 וּגְבַר גְבַר מִבֵּית יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן דִי יֵיכוּל כָּל דְמָא וְאֶתֵּן רוּגְזִי בַּאֲנָשָׁא דְיֵיכוּל יָת דְמָא וֶאֱשֵׁיצֵי יָתֵהּ מִגוֹ עַמֵהּ:
@45 אֲרֵי נְפַשׁ בִּסְרָא בִּדְמָא הִיא וַאֲנָא יְהָבִתֵּהּ לְכוֹן עַל מַדְבְּחָא לְכַפָּרָא עַל נַפְשָׁתֵיכוֹן אֲרֵי דְמָא הוּא עַל נַפְשָׁא מְכַפֵּר:
@46 עַל כֵּן אֲמָרִית לִבְנֵי יִשְׂרָאֵל כָּל אֱנַשׁ מִנְכוֹן לָא יֵיכוּל דְמָא וְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן לָא יֵיכוּל דְמָא:
@47 וּגְבַר גְבַר מִן בְּנֵי יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן דִי יְצוּד צֵידָא חַיְתָא אוֹ עוֹפָא דִי מִתְאֲכֵל וְיֵשׁוֹד יָת דְמֵהּ וִיכַסִנֵהּ בְּעַפְרָא:
@48 אֲרֵי נְפַשׁ כָּל בִּסְרָא דְמֵהּ בְּנַפְשֵׁהּ הוּא וַאֲמָרִית לִבְנֵי יִשְׂרָאֵל דַם כָּל בִּסְרָא לָא תֵיכְלוּן אֲרֵי נְפַשׁ כָּל בִּסְרָא דְמֵהּ הִיא כָּל דְיֵיכְלִנֵהּ יִשְׁתֵּיצֵי:
@49 וְכָל אֱנַשׁ דִי יֵיכוּל נְבִילָא וּתְבִירָא בְּיַצִיבָא וּבְגִיוֹרָא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא וְיִדְכֵּי:
@50 וְאִם לָא יְצַבַּע וּבִסְרֵהּ לָא יַסְחֵי וִיקַבֵּל חוֹבֵהּ:
@51 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@52 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@53 כְּעוֹבָדֵי עַמָא דְאַרְעָא דְמִצְרַיִם דִי יְתֶבְתּוּן בַּהּ לָא תַעְבְּדוּן וּכְעוֹבָדֵי עַמָא דְאַרְעָא דִכְנַעַן דִי אֲנָא מָעֵל יָתְכוֹן תַּמָן לָא תַעְבְּדוּן וּבְנִימוֹסֵיהוֹן לָא תְהָכוּן:
@54 יָת דִינַי תַּעְבְּדוּן וְיָת קְיָמַי תִּטְרוּן לְהַלָכָא בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@55 וְתִטְרוּן יָת קְיָמַי וְיָת דִינַי דִי יַעְבֵּד יָתְהוֹן אֲנָשָׁא וְיֵחֵי בְהוֹן לְחַיֵי עָלְמָא אֲנָא יְיָ:
@56 גְבַר גְבַר לְכָל קָרִיב בִּסְרֵהּ לָא תִקְרְבוּן לְגַלָאָה עֶרְיָא אֲנָא יְיָ:
@57 עֶרְיַת אֲבוּךְ וְעֶרְיַת אִמָךְ לָא תְגַלֵי אִמָךְ הִיא לָא תְגַלֵי עֶרְיָתָהּ:
@58 עֶרְיַת אִתַּת אָבוּךְ לָא תְגַלֵי עֶרְיַת אָבוּךְ הִיא:
@59 עֶרְיַת אֲחָתָךְ בַּת אֲבוּךְ אוֹ בַת אִמָךְ דִילִידָא מִן אֲבוּךְ מִן אִתַּת אָחֳרִי אוֹ מִן אִמָךְ לִגְבַר אָחֳרָן לָא תְגַלֵי עֶרְיַתְהֶן:
@60 עֶרְיַת בַּת בְּרָךְ אוֹ בַת בְּרַתָּךְ לָא תְגַלֵי עֶרְיַתְהֶן אֲרֵי עֶרְיְתָךְ אִנוּן:
@61 עֶרְיַת בַּת אִתַּת אֲבוּךְ דִילִידָא מִן אֲבוּךְ אֲחָתָךְ הִיא לָא תְגַלֵי עֶרְיָתָהּ:
@62 עֶרְיַת אֲחַת אֲבוּךְ לָא תְגַלֵי קָרִיבַת אֲבוּךְ הִיא:
@63 עֶרְיַת אֲחַת אִמָךְ לָא תְגַלֵי אֲרֵי קָרִיבַת אִמָךְ הִיא:
@64 עֶרְיַת אַח אֲבוּךְ לָא תְגַלֵי לְאִתְּתֵהּ לָא תִקְרַב אִתַּת אַח אֲבוּךְ הִיא:
@65 עֶרְיַת כַּלָתָךְ לָא תְגַלֵי אִתַּת בְּרָךְ הִיא לָא תְגַלֵי עֶרְיָתָהּ:
@66 עֶרְיַת אִתַּת אֲחוּךְ לָא תְגַלֵי עֶרְיַת אֲחוּךְ הִיא:
@67 עֶרְיַת אִתְּתָא וּבְרַתָּהּ לָא תְגַלֵי יָת בַּת בְּרָהּ וְיָת בַּת בְּרַתָּהּ לָא תִםַב לְגַלָאָה עֶרְיָתָהּ קָרִיבָן אִנוּן עֵצַת חִטְאִין הִיא:
@68 וְאִתְּתָא עִם אֲחָתָהּ לָא תִסָב לְעָקָאָה לְגַלָאָה עֶרְיְתָהּ עֲלָהּ בְּחַיָיהָא:
@69 וּלְאִתְּתָא בְּרִחוּק סוֹבְתַהּ לָא תִקְרַב לְגַלָאָה עֶרְיְתָהּ:
@70 וּבְאִתַּת חַבְרָךְ לָא תִתֵּן שְׁכֻבְתָּךְ לְזַרְעָא לְאִסְתָּאָבָא בָהּ:
@71 וּמִבְּנָיִךְ לָא תִתֵּן לְאַעְבָּרָא לְמוֹלֶךְ וְלָא תַחֵל יָת שְׁמָא דֶאֱלָהָךְ אֲנָא יְיָ:
@72 וְעִם דְכוּרָא לָא תִשְׁכּוּב מִשְׁכְּבֵי אִתְּתָא תּוֹעֶבְתָּא הִיא:
@73 וּבְכָל בְּעִירָא לָא תִתֵּן שְׁכֻבְתָּךְ לְאִסְתָּאָבָא בָהּ וְאִתְּתָא לָא תְקוּם קֳדָם בְּעִירָא לְמִשְׁלַט בָּהּ תִּבְלָא הוּא:
@74 לָא תִסְתַּאֲבוּן בְּכָל אִלֵין אֲרֵי בְּכָל אִלֵין אִסְתַּאָבוּ עַמְמַיָא דִי אֲנָא מַגְלֵי מִן קֳדָמֵיכוֹן:
@75 וְאִסְתָּאָבַת אַרְעָא וְאַסְעָרִית חוֹבָהּ עֲלָהּ וְרוֹקֵינַת אַרְעָא יָת יָתְבָהָא:
@76 וְתִטְרוּן אַתּוּן יָת קְיָמַי וְיָת דִינַי וְלָא תַעְבְּדוּן מִכֹּל תּוֹעֶבְתָּא הָאִלֵין יַצִיבָא וְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן:
@77 אֲרֵי יָת כָּל תּוֹעֶבְתָּא הָאִלֵין עֲבָדוּ אֱנָשֵׁי אַרְעָא דִי קֳדָמֵיכוֹן וְאִסְתָּאָבַת אַרְעָא:
@78 וְלָא תְרוֹקֵן אַרְעָא יָתְכוֹן בְּסָאֳבֵיכוֹן יָתָהּ כְּמָא דְרוֹקֵינַת יָת עַמְמַיָא דִי קֳדָמֵיכוֹן:
@79 אֲרֵי כָּל דִי יַעְבֵּד מִכֹּל תּוֹעֶבְתָּא הָאִלֵין וְיִשְׁתֵּיצוּן נַפְשָׁתָא דְיַעְבְּדוּן מִגוֹ עַמְהוֹן:
@80 וְתִטְרוּן יָת מַטְרַת מֵימְרִי בְּדִיל דְלָא לְמֶעְבַּד מִנִימוֹסֵי תוֹעֶבְתָּא דְאִתְעֲבָדָא קֳדָמֵיכוֹן וְלָא תִסְתַּאֲבוּן בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן: פפפ:

@1 **וידבר ה' וגו'**. צריך לדעת מה נאמר לו בדיבור זה. ב' לאיזה ענין ישמיענו הכתוב היות דיבור זה אחרי מות, מה לי אחר מה לי קודם. ג' למה הוצרך למור **בקרבתם** וגו', אם להודיע שמתו בשביל שנתקרבו לפני ה', הלא כבר הודיע הדבר במקומו (לעיל י יא) ויקריבו אש זרה וגו', ושם הוא יותר מפורש הדבר ומה שכתוב כאן בקרבתם, שאין ידוע מה הוא העון שעשו בקריבה זו שעליה מתו. ד' אומרו וימותו מיותרת אחר שהתחיל לומר אחרי מות בקרבתם וגו'. ה' אומרו וימותו בתוספת וא''ו:
@1 **ונראה** שכוונת הכתוב הוא שבא הקב''ה להזהיר את משה שלא יחשוב בדעתו כי לצד שהוא יותר קרוב למלכות שמים ובכל ביתו של המקום נאמן הוא ויכול ליכנם אל הקודש פנימה, והגם שיצו ה' על אהרן לא יתחייב הדבר שגם משה בכלל, כי גדול משה דכתיב (במדבר יב) אם יהיה נביאכם ה' וגו' לא כן עבדי משה, אשר על כן דבר ה' אל משה, והוא אומרו **וידבר ה' אל משה** פירוש אליו בא המצוה, ואמר לו סמוך למיתת ב' בני אהרן דיבור זה **בקרבתם** לפני ה' וימותו, פירוש הגם היותם בני אהרן ובתוספת מרובה היותם קרובים לפני ה' כמו שדרשו ז''ל (ויק''ר הי''ב) בפסוק בקרובי אקדש אף על פי כן לא חמל עליהם **וימותו**, הא למדת שלא יועיל היות האדם כל כך קרוב לה' כדי שיפרוץ גדר ליכנס לקודש פנימה:
@1 **עוד** נראה לומר שנתכוון באומרו **בקרבתם** על זה הדרך בהיותם יותר קרובים לה' מכל, הא למדת שאין קרובים מהם, שאם היה משה קרוב מהם היה הדבר נעשה בו כמו שאמר לו ה' (לעיל ג') בקרובי אקדש. ואולי כי כאן ביאר הקב''ה דבריו אל משה, ועל פי הדברים האלה אמר משה לאהרן הוא אשר דבר ה' וגו', כי דיבור זה נאמר לו סמוך לקריבתם ומיתתם. והגם שכבר כתוב בתורה מיתת ב' בני אהרן, אין מוקדם ומאוחר בתורה. ובתורת כהנים אמרו בסלקא דעתין דתיבת אחיך בא למעט משה שאינו באזהרה ומותר לבא בכל עת, והעלו באמיתות הדרשא שתיבת אחיך באה לרבות הבנים שהם באזהרת ע''כ. וכפי זה לא נתמעט משה מאזהרה, ומעתה אין אני יודע מה דינו של משה אם הוא באזהרה או לא. והרב בעל קרבן אהרן כתב שפשיטא כי מי הכניסו עד שיצטרך להזהירו. ולפי מה שכתבתי הנה באה אזהרתו ביחוד בפסוק ראשון. ודברי בעל קרבן אהרן שאמר מי הכניסו אינם נראים. וכונת התנא היא שלא בא הכתוב למעט משה מהאזהרה, ואין לנו מקרא לא למעט ולא לרבות, ובחר התנא לדרוש ביתור תיבת אחיך לרבות הבנים מלדרוש בה למעט משה. וכל זה לסברת האומר (ב''ר מ''ד ה') אחרי סמוך אחר מופלג, וכמו שהעתקתי מחלוקתם במקומות אחרים. אבל לסברת האומר אחרי מופלג אחר סמוך יתבאר הכתוב על זה הדרך שבא להודיעו שמיתתם היתה על קרבתם לפנים בקודש, והגם שהתורה אמרה אש זרה, מודיעו ה' כי טעם מיתתם היתה על קרבתם לפנים הגם שלא היתה אש זרה, ואומרו **וימותו**, נתכוין להודיעו שלא יחשוב כי יצתה מחשבתם לפועל שנכנסו לפנים אלא שנדחפו ומתו, והכוונה בהודעה זו לשלול לבל יחשוב אדם לפרוץ ולהתקרב הגם שימות, וזה ימצא בהיות לאדם בחינת החשק לא יחוש על עצמו ויתן נפשו, ודבר זה ימצא בבחינת החושק שיתן נפשו על הדבר הגם שידע שימות, לזה אמר לו וימותו פירוש וכבר מתו ולא השיגו מחשבתם להתקרב והבן זה:
@1 **וזה** לדעת ר' יוסי הגלילי שאמר בתורת כהנים על הקריבה מתו וגם לסברת ראב''ע שאמר כדי קריבה לעצמה וכדי הקרבה לעצמה, אבל לדברי רבי עקיבא דאמר על ההקרבה מתו, הנה לסברת האומר אחרי מופלג יתבאר הכתוב באופן אחר, והוא בהקדים לחקור למה לא ציוה ה' על משפט יום הכפורים האמור בפרשה זו עד הן היום ולא צוה ביום צוותו בענין קדשי המשכן, וכאשר אמר לו (שמיני ט ז) קרב אל המזבח שם היה לו לומר לו לא יבא אל הקודש פנימה. האמת שמדוייק הוא האיסור מאומרו קרב אל המזבח ועשה את וגו', שלא היה לו לומר אלא עשה את חטאתך וגו' ולמה הוצרך לומר קרב וגו', ורז''ל (בתו''כ) דרשו דרשות, ולדרכנו נראה שאמר אליו קרב אל המזבח אין לך רשות ליקרב אלא למזבח ולא לפנים, אלא ששם היה לו לצוות באזהרה זו דאל יבא וגו' ולא ימות:
@1 **אכן** לצד מה שהודיענו הכתוב שבעון העגל מתו שני בני אהרן דכתיב (עקב ט כ) ובאהרן התאנף ה' להשמידו ואתפלל וגו' ופירשו רז''ל (ויק''ר פ''ז) להשמידו זה מיתת הבנים והועילה תפלתו של משה מחצה, הא למדת כי שני בני אהרן בעון העגל מתו ומזבח כפרה היו המה לאביהם, ולא תקשה והלא אמרו (תו''כ כאן) שמתו לצד עון הקריבה למאן דאמר ולמאן דאמר על ההקרבה. יש לומר שאם לא היה עון אביהם היה ה' שומר רגלי חסידיו. גם לא קשה על מה שאמרו (זבחים קטו) שמתו להתקדש שמו יתברך, כי אם לא היה עון העגל היה מתחייב מאלהי המשפט להתקדש הבית בזולתם, כי כבר הודעתיך שהגם שיחפוץ ה' המותה לחסידיו לסיבה נעלמת לידוע תעלומות נפלאים ורמות, צריך שיהיה לצדיק כל שהוא מהדברים אשר לא טוב עשות כדי שדרך שם ישלוט בהם הדין. וכבר הארכתי בענף זה, צא ולמד (אבדר''נ פל''ח) ממה שמצא רע''ק טעם להריגתו לצד ששמח לבו בדרשתו תוך ס' ריבוא כאמור בדבריהם, וקשה הלזה יתחייב אנוש מיתה משונה אם כן פקע כלילא דורדי מכל עושי טוב ולומדים, אלא דזה הוא דרך שממנו ישלוט בו הדין, ולעולם סיבת מיתתו יקר בעיני ה' המותה לעשרה הרוגי מלכות למגן וצינה לדורות בני ישראל. וטעם זה נותן טעם לשבח גם במה שלפנינו, כי עון העגל כבר נמחל בפרהסיא כשהקריב אהרן אל המזבח וירדה שכינה על ידו ונתבשר שנמחל לו עון העגל, אם כן בטל דינא דהשמדת הבנים שבהבטל הסיבה יבטל המסובב, אלא ודאי כי הגם שנמחל רישומו ניכר והוא כשיעור חוט השערה מהחטא שיספיק להשלטת מדה הפועלת דין באדם, וזה גרם שלא נשמרו רגלי חסידיו ושגגו בקריבה והקרבה, ונתקדש בהם הבית:
@1 **ועל** פי הדברים האלה נוכל לומר כי לא הוכשר אהרן להיות ראוי לבא אל בית חצר המלך פנימה אלא באמצעות מזבח כפרה של הבנים בניו ונמחה רושם חטא העגל, אבל זולת זה לא הוכשר אהרן למעלה עצומה לעמוד במקום מופלא ובזה יתישב הכתוב על נכון, **וידבר ה'**, ומודיע הכתוב כי הדיבור הנאמר בענין **בזאת יבא אהרן אל הקודש** לא נכשר אהרן למעלה זו אלא **אחרי מות שני בני אהרן** ונמחה חטאו ודקדק לומר **בני אהרן**. כאן רומז כפרת עון אביהם שבזה הושלם להיות ראוי להאמור בענין כמו שפירשתי. ובזה נתן הכתוב טעם למה לא צוה ה' את הדבר הזה עד הנה, כי מקודם לא היה מוכשר אהרן לזה, ואחר שנחת הכתוב להודיע סיבת מיתתם שהוא לצד היותם בני אהרן לכפרת עון אביהם הודיע כי לא זאת היא סיבתם מתחלה ועד סוף למיתתם, אלא זאת היתה סיבה ראשונה שהיא גרמה שלא נשמרו רגליהם כנזכר ושגגו בקריבה או בהקרבה למאן דאמר, והוא אומרו **בקרבתם לפני ה'** לומר כי מה גרם להם היותם בני אהרן שיש בידו עון מעשה העגל הוא קרבתם, ובהצטרפות מכשול זה מתו. ולצד שכפי האמת ב' סיבות הללו לא הספיקו למיתתם, רבתי הוא אשר דבר ה' (לעיל י ג) בקרובי אקדש, שמתו להתקדש הבית בשבילם, כאשר אבאר טעם הוצרך לטעם זה ולא הספיקו ב' הטעמים, לזה אמר וימותו בתוספת וא''ו לרמוז ענין צורך מיתתם להתקדש הבית לירא את ה' המקודש לירא מהמקדש כל הקרב לבל ימות גם הוא ולזה סמך דיבור אזהרת אהרן **ואל יבא** וגו' **אל הקודש**. נמצאת אומר ג' דברים גרמו מיתתם, עון העגל, וההקרבה, וקידוש הבית, ושלשתם הודיע ה' במאמר ראשון שאמר **אחרי מות שני בני אהרן** זה כנגד חטא אהרן, **בקרבתם** כמשמעו, **וימותו** בשביל לקדש הבית **לבל יבא** וגו' **אל הקודש** קטן וגדול, וכל ג' הטעמים צריכין, עון העגל שזולתו לצד שהיו צדיקים גמורים היה הדין מחייב שיהיו נשמרים לבל יכשלו בקריבה וזה סימן למכשול ועון הקריבה גם כן שזולתה לא יומתו על עון אביהם כי גדולים היו, וסיבת קידוש הבית שזולת זה לא היה ה' מערבב שמחתו ביום שמחת לבו, ויתחייב הדבר לשמירת רגליהם לבל יכשלו, או לא היה ה' ממיתם באותו יום והיה ממתין להם עד יום אחר, אלא לצד שרצה ה' לקדש הבית בו ביום עשה כן. וטעם זה לבד לא יספיק למיתתם, שיתקדש הבית בזולתם:
@1 **וכפי** זה אפשר לתת טעם למאמרם ז''ל שאמרו (תו''כ שמיני) שאמר משה על נדב ואביהוא שהם גדולים ממשה ואהרן כי ממה שראה משה שהוצרך טעם עון העגל למיתת בני אהרן אם כן לא מצא הקב''ה נדנוד עון להסתבך בו ענף הדין ולא נכשלו אלא לצד מה שקדם בעון אביהם, לזה אמר שהם גדולים ממשה ואהרן כי לא נמצא להם אפילו כחוט השערה מהחטא מה שאין כן משה ואהרן. ולדרכנו זה אפשר שלזה נתכוון הכתוב באומרו (משלי כב) הלא כתבתי לך שלישים במועצות ודעת, כי ג' דברים היו סיבה לדבר, במועצות ב', ודעת ג', והם ג' דברים האמורים בענין, כנגד מה שלא מחל ה' לאהרן לעון העגל לא בתפילה ולא בהרצאת אהרן בקרבנותיו ומעשיו, גם כנגד מה שלא שמר רגליהם מלהתקרב למקום מקודש אמר במועצות, כי נתיעץ ה' לתכלית דבר, ורמז לב' הדברים במה שאמר מועצות לשון רבים ב' עצות, וא' מסובבת מחברתה, שלא החליט מחילה לאהרן כדי שלא ישמרם שבזה תמצא מדה השולטת כנזכר, וכנגד תכלית הדבר שמתו לקדש שמו יתברך אמר ודעת פירוש להודיע לכל מה יקר מקום קדושתו שאפילו לאנשים צדיקים כאלו שאין כמותם היה מה שהיה ויתקדש הבית:
@1 **עוד** נתכוון באומרו **אחרי מות** להיות שיצוה ה' לבל יכנס אהרן לקדשי קדשים בבגדי זהב (ראש השנה כו) מטעם אין קטיגור נעשה סניגור חש הכתוב לבעל דין שיחלוק ויאמר כי לא הקפיד ה' על הכנסת אהרן בבגדי זהב אלא כל עוד שעדיין לא נמחה רישומו של עון העגל, מה שאין כן אחר שמתו בניו ואין רישומו של עגל ניכר לחלוטין נמחה קטיגורו של זהב ויכול ליכנס בבגדי זהב בכבוד ובתפארת, לזה אמר **אחרי מות** וגו' שגם אחרי מותם צוה ה' לבל יכנס בבגדי זהב לקודש הקדשים אלא **כתונת בד קודש** וגו'. והגם שאמרו ז''ל (ערכין טז.) שבגדי זהב מכפרים. אף על פי כן לא יעשה קטיגור סניגור ללבן עונם של ישראל כשלג. ועיין מה שכתבתי בימי חורפי בחפצי חפץ ה' במאמרם ז''ל (שבת ל.) שכשאמר שלמה זכרה לחסדי וגו'. ולדרך זה אומר **בקרבתם** בא להסיר חשש פגם מעל משה שהוא אמר (עקב ט כ) ואתפלל גם בעד אהרן ויאמר האומר שלא הועילה תפילתו של משה, ומשה עצמו יחשוב מחשבות שלא הועילה תפילתו, לזה אמר **בקרבתם** לפני ה' פירוש בהצטרפות סיבה זו מתו אבל זולת זה והלא היו מתים כי הועילה תפלתו של משה על אהרן לבל ישמידו, וכפי זה אין אנו צריכין לומר שהועילה מחצה ולדבריהם ז''ל (ויק''ר פ''י ה') שאמרו שהועילה מחצה, פירוש כיון דסוף סוף מתו לא יהיה תועלת מתפלתו של משה לאהרן אלא מחצה כי אינו חשוב תועלת אלא כפי תכלית. ואומרו וימותו, אולי שבא ה' לומר למשה כי האנשים האלה עשו עון הקריבה או הקרבה והם כבר היו חייבי מיתה מעת התרגז ה' על אהרן להשמידו ולזה לא נמנעו מיד מדת הדין, אבל אם לא היה מה שקדם שהיו בני מיתה כנזכר הגם שהיו נכנסים אפשר שהיה ה' מאריך אפו להם וכדומה לזה, ושיעור הכתוב על זה הכתוב **בקרבתם לפני ה'** ומקום זה צריך לעשות להם נם למלטם מיד מדת הדין והם וימותו כבר פירוש נתחייבו מיתה קודם אלא בתפלת משה נמלטו:
@1 **או** יאמר על זה הדרך **אחרי מות** וגו'. דבר ה' למשה דרך מיתתן שהיתה על זה הדרך **בקרבתם לפני ה'** פירוש שנתקרבו לפני אור העליון בחיבת הקודש ובזה מתו, והוא סוד הנשיקה שבה מתים הצדיקים, והנה הם שוים למיתת כל הצדיקים, אלא שההפרש הוא שהצדיקים הנשיקה מתקרבת להם ואלו הם נתקרבו לה, והוא אומרו **בקרבתם לפני ה'**, ואומרו **וימותו** בתוספות וא''ו, רמז הכתוב הפלאת חיבת הצדיקים, שהגם שהיו מרגישים במיתתם לא נמנעו מקרוב לדביקות נעימות עריבות ידידות חביבות חשיקות מתיקות עד כלות נפשותם מהם והבן ובחינה זו אין מכיר איכותה, והיא מושללת ההכרה, לא מפי מין האנושי, ולא מפי כתבו, ולא תושג בהשערות מושכל הגשם, ולמשיג חלק מהשגה זו תבדיל ממנו המונע אותו מהתקבל ותכירהו על ידי סימניה כי זה הפכה מנגדת שונאיה ותפעול בו פעולה רשומה לשלול ממנו כח המונעו והמקיימו, ולפעמים תמאסהו הנפש ותריבהו מריבה גדולה והוא סוד הוללות הנביאים (ש''א יט כד), ולכשתרבה בחינה זו בפנימיותו תגעל הנפש את הבשר ויצתה מעמה ושבה אל בית אביה. ואודיע למתבונן בפנימיות השכלת המושכל, שהשכלת ההשכל תשכיל ההשכלות, ובהשכל בהשכלתו, ישכיל, שמושכל מושלל ההשכל, וכשישכיל בהערת עצמו, ולא עצמו ישכיל, שהמושכל מושכל ממושכל, בלתי מושכל מהשכל, והשכילו למשכילים ביחוד, השכלתו בסוד נשמה לנשמתו. ואז מותריו יהיו עטרי מלכים וכסאם. וכי יש חיים לחיים שעליהם אמר משה (נצבים ל יט) ובחרת בחיים בית המודעות, ושוללת חיים הנשתוים בהרגש הכללי, ויברך ברוך אלהים חיים אשר סגל סגולה זו לסגולתו:
@1 **עוד** יתבאר על דרך אומרם ז''ל בתורת כהנים והובאה במסכת יומא (נג.) וזה לשונם תניא ר''א אומר ולא ימות עונש, כי בענן אראה אזהרה יכול קודם מיתת בני אהרן, תלמוד לומר אחרי מות, יכול שניהם אחר מיתת וכו', תלמוד לומר אראה וגו', הא כיצד אזהרה קודם, מיתה עכ''ל. ובמס' יומא פ''ה (שם) בעי מאי משמע, ואמר רבא דכתיב אראה ועדיין לא נראה, ואילו היה אחרי מות בני אהרן כבר נראה בו ביום שנאמר (ט כג) וירא כבוד ה' ע''כ. וכפי זה בני אהרן מתו קודם שהעניש הכתוב. וכפי זה יתבאר הכתוב על זה הדרך אומרו **אחרי מות** בא לבל תחשוב בראותך כי יצוה ה' מצות הקטורת ואמר ולא ימות נאמר כי הוא זה עונש שבו נענשו בני אהרן דכתיב (י יא) ויקחו בני אהרן וישימו עליה קטורת וגו', לזה אמר **אחרי מות** וגו' פירוש כי לא צוה בעונש אלא אחר שמתו בני אהרן וגו'. אם כן לפי זה חלה הקושיא למה מתו. לזה אמר כי לא מתו על קו המשפט שאחרים אם היו עושים דבר זה לא היו מתים כיון שעדיין לא נצטוו בעונש, אלא הטעם הוא **בקרבתם לפני ה'** להיותם סביביו של הקב''ה דקדק עמהם כחוט השערה, ודבר קטון יחשב לדבר גדול, והוא מה שרמז בתוספות הוא''ו של וימותו לומר הגם שלא היו מחוייבים מיתה מטעם שעדיין לא ענש אף על פי כן מתו:
@1 **ובתורת** כהנים אמרו וזה לשונם דבר אל אהרן וגו' אין אנו יודעים מה נאמר בדיבור ראשון, היה ראב''ע משלו משל למה הדבר דומה לחולה שנכנם אצלו הרופא אמר לו אל תאכל צונן ואל תשכב בטחב, בא אחר ואמר לו אל תאכל צונן וכו' שלא תמות כדרך שמת פלוני, זה זרזו יותר מן הראשון, צריך לדעת למה אמר בסדר זה היה רבי אלעזר בן עזריה שהיה לו לומר אמר רבי אלעזר בן עזריא וכו':
@1 **ונראה** כי רבי אלעזר בן עזריה לא לקושיא זו נתכוין אלא על קושיא אחרת בא לתרץ, והיא מה שהקשינו למה איחר ה' לצוות מצוה זו לאהרן עד עתה, והיה מושלו לרופא וכו' שהרופא המזרז הרבה הוא שאומר כדרך שמת פלוני, וכמו כן עשה רופא ישראל שהמתין עד שמתו בניו כדי לזרזו ביותר, ומביא התנא דברי רבי אלעזר בן עזריה לתרץ גם קושיות כפל הדיבורים ובכללי הגמרא אנו אומרים שלפעמים מזכיר בעל המאמר בתירוץ ולא בקושיא, אלא שהתנא מביא דבריו לתרץ גם מה שהוקשה לו מה נאמר לו בדיבור ראשון כי נאמר לו הבט וראה שהאנשים הנגשים אל ה' קדשו ותבער בם אש הקדושה כה תאמר לאהרן אחיך גם הוא אל יבא וגו'. אלא דקשה לפי זה היה לו לומר אחרי מות ב' בני אהרן אחר דבר וגו', או אחר אומרו וידבר:
@1 **וראיתי** בסוף הברייתא דרבי אלעזר בן עזריה שגמר אומר וזה לשונו וזה זרזו (יותר) מהראשון לכך נאמר ויאמר וגו' דבר אל אהרן שאמרתי לך (שמות ד יד) הלא אהרן אחיך הלוי וראך ושמח בלבו, ואל יבא וגו' ואם יבא הוא מת עכ''ל. צריך לדעת מנין מצא לומר שאמר לו ה' הלא וגו' וראך וגו'. והיה נראה שהוקשה לו יתור תיבת אחיך, ולזה דרש אחיך שאמרתי לך הלא אהרן אחיך הלוי, והכונה כי יפחידו שלא יארע לו כמו שאירע לבניו, והצד שממנו יתחייב אמר לו כל זה הוא לצד היותו אחיו אחוה נכונה ונאמנה, אלא שקשה כי בתורת כהנים דרש מאומרו אחיך לרבות בני אהרן וכמו שכתבתי למעלה, ואפשר דדרשינן שניהם ודוחק:
@1 **ונראה** שכונת המאמר הוא ממה שאנו רואים שה' אמר למשה מה שצריך שיאמר לאהרן שלא ימות כבניו, ומן הראוי היה לו לומר זה אחר ויאמר ה' דבר אל אהרן לא מקודם, לזה אמר כי להיותם ב' אחים הנעימים אוהבים זה את זה כאומרו הלא אהרן אחיך הלוי ורמז לו (זבחים קב) שיטול כהונה ולא הקפיד, גם אהרן בראותו אחיו הקטן יגדל ממנו ואף על פי כן שמח בלבו, אשר על כן הוא אומר למשה דבר הנוגע לאהרן, ונתכוין ה' בזה להיות כולם כאיש אחד, ואם נאמר שמה שדרשת דבר אל אהרן שאמרתי לך הלא אהרן וגו' הוא דרשה בפני עצמה ואינה גמר דרשה שלפניו נראה כי אומרו ואל יבוא בתוספות וא''ו. ולפי פשט הכתוב נראה לומר כי באומרו ואל יבא בתוספת הוא''ו ולא הספיק לו לומר אל יבא, לרמוז שלא יוסיף הוא לעבור עליו מה שעבר על בניו, וכפי זה כאילו ביאר הכתוב שלא ימות גם הוא כבניו:
@1 **וראיתי** להרא''ם ז''ל שפירש כי לדברי רבי אלעזר בן עזריה יש ג' מיני אזהרות, והאריך ליישב הכתובים לדברי רבי אלעזר בן עזריה ולפי דעתי לא נתכוין רבי אלעזר בן עזריה אלא לומר שבדיבור ראשון אמר ה' למשה שיאמר לאהרן שאם יעבור ימות כדרך שמתו בניו, והוקשה לו לאיזה ענין יצוה ה' ככה ולא הספיק באומרו ולא ימות, לזה המשיל הדבר לרופא שהרופא שאומר לחולה שלא ימות כדרך שמת פלוני הוא מזרזו ביותר על כן צוה ה' ככה לתוספות זירוז, ורבי אלעזר בן עזריה לא המשיל הדבר ברופא א' אלא בג' רופאים וכל רופא שיער זירוז א' ורופא המזרז ואומר שלא ימות כפלוני לא הוא שזרז פעם ראשונה ושניה, וכפי זה סדר שעשה ה' הוא כרופא המזרז יותר מכלן, ולפי דברי הרא''ם אינו דומה לא לרופא א' ולא לב' ולא לג', כי רופא א' וב' אינם אומרים כפלוני והג' הוא מזרזו בפעם אחת ואומר לו שלא ימות כפלוני, מה שאין כן הקב''ה שלא ציוהו כן עד פעם ג'. ולדברי הרא''ם צריך לדחוק ולפרש שהדמיון הוא נושא א' לג' נושאים יחד. ועדיין קשה לדבריו למה עשה רבי אלעזר בן עזריה הדמיון בג' נושאים ולא בנושא אחד כדי שישוה אליו הנדמה, אלא ודאי שלא צוה אלא פעם אחד ובאחת דבר אליו הזירוז שלא ימות כבניו. ופירוש הכתובים לדבר רבי אלעזר בן עזריה הם על זה הדרך, וידבר וגו'. אחרי מות דיבור אחד. דבר וגו' ואל יבא וגו' דיבור ב'. בדבור אחד נאמר לו אמור לאהרן שבניו מתו בשביל ההקרבה, ואמור דיבור ב' שאני מצוהו לבל יקרב גם הוא, וממוצא דבר מובן כי מזרזו לבל יארע לו כדרך שמתו בניו, והוא דמיון הרופא הג' שזרזו יותר מכולן:
@2 **ויאמר ה'**. טעם לשון אמירה, לצד שהאזהרה באה בתוקף שאם יבוא ימות כמו שדרש רבי אלעזר בן עזריה (תו''כ כאן). לזה הודיעו כי אין זה אלא חיבה יתירה כדרך הרופא שמשתדל לזרז החולה לבל ימות, וכדמיון רבי אלעזר בן עזריה והוא מה שרמז בלשון אמירה:
@2 **או** ירצה כי ה' גדל ורמם את משה שגם דיבור הנוגע לאהרן לבדו לא דבר ה' עם אהרן אלא עם משה, והוא אומרו **ויאמר ה' אל משה** על דרך וה' האמירך, ותמצא שאמרו ז''ל (מד''ר פ' נשא פי''ד כ''א ריש תו''כ) שאפילו במקום שאמר הכתוב וידבר ה' אל משה ואל אהרן הכוונה בו למשה שיאמר לאהרן, וזה לך האות שאפילו מצות אהרן לא נאמרה לאהרן, ואם היה ה' מדבר עם אהרן לא היה צריך לצוותו על ידי שליח:
@2 **ואל יבא** אמר וא''ו בתחילת דיבור, מלבד מה שכתבנו למעלה, נראה עוד לומר כי לצד שקדם משה ואמר לאהרן ביום א' למשיחתו (לעיל ט ז) קרב אל המזבח ועשה וגו' משמעות הדברים יגידו כי למזבח יקרב ולא לפנים מן המזבח, ואמרו מאורי עולם שהם רבותינו ז''ל (פסחים מא:) כי לאו הבא מכלל עשה עשה, ומעתה הרי קדם לו על הכניסה עשה, לזה הוסיף כאן לאו על הדבר ואמר **ואל יבא**:
@2 **בכל עת** אבל יש עת שיבא בה, והוא מה שאמר אחר כך בזאת יבא וגו' אחת בשנה. וטעם שהקדים **ואל יבא בכל עת** קודם מצות ביאתו אחת בשנה, לומר אם לא יבא בכל עת אז יזכה לבא בעת ההיא אשר אנכי מצוך ואם יבא בעת אחר לא יבא בכל עת אפילו בעת הרשיון. ודקדק לומר **בכל עת** דרשו רז''ל (בתו''כ) שבא לאסור אפילו ביום כיפור עצמו לא יכנום אלא לדברים הרשומים בכתב אמת להקטיר ולהזות, ולדרך זה הרווחנו דקדוק נכון אחר בתוספת וא''ו של **ואל**.
@2 **יבא**, לומר מלבד אזהרת ימות השנה עוד מוסיף לומר שאפילו ביום כיפור עצמו לא יבא, ואזהרה שאר ימים דרשו ז''ל (בתו''כ) מהפסוק עצמו שאמר אל הקדש ולא הספיק לומר מבית לפרוכת ומובן המקום אשר יצוה עליו. ואל יקשה בעיניך הקדמת הוא''ו, כי כן דרך הכתוב, ובמקומות אחרים הארכתי בהוכחת הדברים:
@2 **כי בענן אראה**. פירוש לצד שקדם הכתוב ואמר (ט כג) וירא כבוד ה' הודיע כי לא בחינה זו לבד היא הנמצאת בפנים אלא בחינה גדולה אור עליון כי גבוה מעל גבוה שומר, והוא אומרו **אראה על הכפורת**:
@3 **בזאת יבא אהרן**. טעם שהזכיר אהרן ולא סמך על זכרונו בתחלת הענין, לצד שמה שקדם במצוה לא היה אלא לאהרן לבדו שלא יכנס ולא ימות, ואין מצוה זו נוגעת לזולתו, ומכאן ואילך לא לאהרן לבד באה המצוה אלא גם לכל ישראל כי הוא צורך ישראל לכנס לבית קדשי קדשים לכפר עליהם אחת בשנה, ויצו האל לעמו לעשות החוקים האמורים שיכניסו אהרן בפר וגו' כתנת בד קודש וגו' ודרשו ז''ל (תו''כ כאן) משל קודש שהיא תרומת הלשכה, וכפי זה יתחייב הכתוב להזכיר שם המצוה בכינוי להם:
@4 **כתנת בד קודש**. עם אומרו קודש בכתונת ולא הספיק במה שגמר אומר בגדי קודש הם. אולי שחש הכתוב שידון אדם בדעתו שלא צוה ה' לעשות משל קודש אלא ג' הבגדים חוץ מן הכתונת, כי הכתונת הוא מלבוש המתחייב לכל אדם ללבוש ויהיה משלו ועל הג' הוא שאמר בגדי קודש שהם בגדים שיכולים להיות לצד כבוד משרתי עליון, לזה אמר **כתונת בד** וגו' שגם היא קודש. וכדי שלא תחשוב כי דוקא כתנת חקק ה' שתהיה של קודש לזה חזר ואמר **בגדי קודש הם** כולם יחד. עוד נראה לומר כי מתכוון לומר ב' דברים, הא' שהבד שיעשו ממנו הכתונת יהיה של קודש, והוא הדין לשאר בגדים, והודיע הכתוב המשפט במזדמן ראשון, וענין ב' הוא שגם מעשה הבגדים יהיה של קודש, והוא מה שגמר אומר **בגדי קודש הם**:
@4 **עוד** נראה כי מתכוון באומרו **בגדי קודש הם**, לבל יראה הדבר שהוא חוץ מהמוס' כי עבד מלך שהוא הכהן אשר פארו ה' וכבדו במלבושי כבוד דכתיב (תצוה כח ב) לכבוד ולתפארת ובעת אשר יתעלה לשירות גדול כזה יאמר אליו הורד עדיך מעליך, לזה אמר **בגדי קודש הם** פירוש בגדים הראוים לקודש הם ולא אחרים, והטעם כי הבגדים המפוארים ההם יש בהם דברים בגו כמאמרם ז''ל (ויק''ר פכ''א ר''ה כו) אין קטיגור נעשה סניגור. או ירמוז טעם (משלי כה) אל תתהדר לפני מלך אדונינו ב''ה קדוש ונורא שמו, והוא אומרו **בגדי קודש הם** פירוש שבהם ראוי להשתמש בקודש קדשים אשר חונה שם האלהים. ורז''ל אמרו קודש ילבש שיהיו של קודש, פירוש כל הד' נלמדים מכתונת שיהיו של קודש וחזר לומר **בגדי קודש הם** דרשו ז''ל (תו''כ) שבא ללמד על כל בגדי כהונה שיהיו של קודש, ואלו ואלו דברי אלהים חיים:
@7 **ולקח את שני השעירים וגו'**. פרשה זו צריכה למודעי כי למה יצוה ה' דבר כזה, ואם היא מהמצות אשר לא עשה ה' בהם טעם היה לו לומר חוקה ומה גם תגדל הקושיא לדבריהם ז''ל (רע''מ אחרי סג. זהר ח''ג קא) כי עזאזל היא בחינת צד הרע הנה כמעט ח''ו שירמה הדבר לעכו''ם, ומה גם שמצוה ה' (יומא פו.) להשוות שעיר של שם לשעיר זה של דבר אחר הדברים מבהילים:
@7 **ונראה** לומר על פי הקדמות שהודיענו רז''ל וזה יצא ראשונה תנן במשנת חסידים (אבות פ''ד) העושה מצוה אחת קונה לו סניגור אחד והעובר עבירה אחת קונה לו קטיגור אחד ע''כ. ומפורשים הדברים באר היטב על פי דברי הזוהר הקדוש (ח''ב עו, ח''ג קכב והע''ז) ובהשכלה מושכל עליון על פי האריז''ל לבאי בהיכלי מלך כי מהעבירה עצמה יולד דבר רע שהוא עצמו העון שעשה ובידו נמסר עושהו כאומרו תיסרך רעתך (ירמי' ב) ותמוגנו ביד עונינו, (ישעי' סד) ולזה כמשמחל ה' לדוד הודיעו שאבד הכח הרע שנולד מהמעשה הבלתי הגון כאומרו (שמואל ב יב) גם ה' העביר חטאתך לא תמות, הכוונה בזה כיון שהחטא שעושה האדם נברא ממנו הנפרע מעושהו ממילא באבוד המשחית אין משחית, וזה שאמר לו ה' שאחר שהעביר חטאתו לא ימות כי אין ממית, מעתה כיון שעל ידי המעשים נוצרים דברים הרעים המזיקים והמצערים את האדם צוה ה' המעדיף טובו עלינו ואמר כי כל שעושה דבר בלתי הגון בלא ידיעה מחטאות האדם יביא קרבן, וצוה שיסמוך עליו בעל הקרבן, והטעם כי בזה יורקו החיצונים ההם שנתהוו ממעשיו הרעים על הקרבן ההוא, ופעולה זו הודיע ה' שתעשה בסגולת הבאת האדם קרבנו לבית אלהינו וסומך עליו שם יעשה הדבר בכח השלם של אלהי הרוחות לכל בשר, וזה הוא טעם שצוה ה' הסמיכה בחטאות, והנה כל המעשה אשר יעשה בחטאת זבח והקטרה יפעיל בבחינת ההיא הנמשכת מהאדם בקרבן ההוא על ידי סמיכתו כנזכר, ובזה היא נעקרת בחינת הרע. וכבר ידעת כי אין חטאת באה אלא על החטאות שהוא הדבר שעושה האדם בשוגג משום דלא נפיש זוהמיה מה שאין כן על עון שעושה האדם במזיד דנפיש זוהמיה אין מביאין קרבן, וזה אמר (משלי כא) זבח רשעים תועבה כי יתעבהו ה' ב''ה להקריב על מזבחו תיעוב כזה שאין לך מיאוס בעולם כמיאוס וזיהום העון רחמנא ליצלן:
@7 **ולפי** הקדמה זו יתבאר הענין על נכון, בהקדים מה שכתבו רז''ל בתורת כהנים וזה לשונם וכפר על הקדש מטומאת בני ישראל ומפשעיהם וגו' על זדון טומאת מקדש וקדשיו שעיר הנעשה בפנים ויום כיפור מכפר ועל שאר עבירות שבתורה הקלות והחמורות הזדונות והשגגות הודע ולא הודע עשה ולא תעשה כריתות ומיתות בית דין שעיר המשתלח מכפר עכ''ל. ובש''ס וזה לשונם ושעיר של עזאזל נושא עליו כל הזדונות קלות וחמורות ושגגות וכו', וגם הכהנים כפרתן בשעיר המשתלח כאמרם ז''ל במסכת זבחים פרק א' (מנחות צב. שבועות יג:) וזה לשונם ר' יהודה אומר גם הכהנים מתכפרין בשעיר המשתלח. ואחר שהודיענו ה' את כל זאת הנה שלך לפניך טעם מספיק כי הב' שעירים נושאים כל זוהמי תחלואי הנפש. השעיר שנושא עליו זדון טומאת מקדש וקדשיו קבלו ה' ולא תעבו, אבל שעיר הנושא זוהמות כל העבירות קלות וחמורות צוה ה' שיאבדם ויכלם חוץ ממקום הקודש, וצוה שיסמוך אהרן עליו את ידיו שהוא שלוחם של ישראל וכל אשר עושים שם הוא היה עושה ששלוחו של אדם כמותו, ואמר ונתן אותם על ראש השעיר החי ביאר הכתוב היטב הדבר שבסמיכתו הוא נותן כל הטומאות המזוהמות ההם על ראשו. ואמר ונשא השעיר, מודיע כי ימצא בו בחינת המקבל לישא את הרע ההוא אל ארץ וגו':
@7 **ולהבין** הענין משל למלך שבקר בגדי בניו וראה בהם בגדים נקיים וכתם בו משפשפו בידו ונותנו לבנו, וכשראה בגד מלוכלך הרבה נותנו לעבד אחד מעבדיו אשר לא ימאס הדבר המאוס, כן הדבר הזה המלך הוא מלכנו יתרומם שמו כשמביא לפניו קרבן אם הוא בפרט וטהרת כתם כל שהוא שהם כתמי השגגה או פרט אחד של טומאת מקדש וקדשיו כנזכר לא יתועב הקרבן אליו, אבל כל הזוהמה של כל העבירות שעשו ישראל קלות וחמורות הוא מיאוס גדול ואמר שיוליכוהו לעבד אחד מהרחוקים מהמלוכה לצד היותו מהפחותים וקלי הערך והוא ישבר ויאבד וימחק אותם ואין זה אלא כנותן לו שירות מבוזה לעשות ואף על פי כן למעלה הוא לו שחשבו האדון לעשות לו דבר ממה שהיה לפני אל בבית המקדש, ונעשה השעיר ההוא בהשואה עם השעיר המתקרב לפני אל. וטעם שצוה ה' עשות ככה ולא אמר שיקחו שעיר מהשוק וישלחוהו לעזאזל אחר שהתודה עליו, הוא לצד כי מן הנמנע שיתקבצו כל הטומאות שעשו ישראל במעשיהם הרעים ויבואו על ראש השעיר כי אם בהביאו השעיר לפני ה' ואחר שהובא לפני ה', מאז מוכח כי הוא זה השעיר שישא כל התיעוב וילך לו אל ארץ גזרה, לזה צוה להגריל והוא הבוחר יבחר את השעיר אשר יבחר בתבונתו יתברך בבעלי חיים, ומה גם למה שאמרו המקובלים כי כמה נפשות וניצוצות בבעלי חיים בלתי מדבר ומי ידע בלתי יתברך שמו. גם יש סוד בגורל (זהר ג' ק''א) והבן:
@10 **יעמד חי**. צריך לדעת הכוונה ורז''ל (יומא מ תו''כ) דרשו הרבה דרושים. ולדרכנו יתפרש על נכון שנתכוון באומרו יעמד חי שלא יתודה עליו תיכף ומיד כשיעלה עליו הגורל אלא יניחהו חי, פירוש לצד כי בחינת הרע נקראת מת ועל שמה יקרא הגוף בלא נשמה מת להיות ששולטת בו בחינת הטומאה הנקראת מת, והשעיר של עזאזל כשמתודה הכהן עליו ונותן עליו כל העונות והפשעים וכו' הנה הוא מת כלול מכל מיני מיתות, וצוה האדון שלא יעשהו מת אלא יעמד חי, ולזה תמצא שאומר עוד אחר כך וסמך אהרן וגו' **על ראש השעיר החי והתודה** וגו' **ונשא השעיר עליו**, כי מתחלה קודם שהתודה קראו חי ואחר כך אמר השעיר ולא הזכיר החי לומר שאחר שהתודה עליו אינו חי שכבר כחות של מיתה ירדו עליו, ותמצא שצוה ה' שהמשלחו טמא ויכבס בגדיו ורחץ בשרו במים כדין טמא מת:
@26 **והמשלח וגו' לעזאזל**. צריך לדעת מה הוא עזאזל ורז''ל (יומא סז:) פירשו עז וקשה. ויש בזה הרבה דרשות על כל פנים אין הדעת מתישבת. ויאורו עיני בדברי אנשי אמת שונין בש''ע נהורים של תורה שאמרו (זוהר ח''ב קנז.) כי המדבר החרוב הוא מקום ס''מ הרשע, וכפי זה בחינת זו תקרא מדבר, ותקרא עזאזל, ותקרא עוזא ועזאל, שאמרו ז''ל שלהם ירמוז שם זה, ואולי כי התיבה תגיד זה על זה הדרך עז אזל פירוש מקום של אותם שאזל ואסף עז פארם. או על זה הדרך עזא ז''ל פירוש מקום של כח הזל ההוא לשון זילות ופחיתו' כי ס''מ הוא למטה במדרגה מכל משרתי עליון:
@29 **והיתה לכם וגו'**. טעם אומרו **לכם**, לצד שבתחילת הדבור אמר אליו ה' דבר אל אהרן ועכשיו בא לצוות את ישראל כמו שגמר אומר האזרח והגר לזה הוצרך לומר **לכם**, לבל תטעה לומר כי מצות הכהנים ביום כיפור הוא דיבור ראשון שצוה ה' בתחילת הפרשה לבד, ומצות ישראל היא העינוי שכן רשם בדת ה', גם השכל יסכים לזה שהכהנים פטורים מהעינוי. או הכהן הגדול מיהא במקום עינויו היא עבודתו, וגם משה תבא הסברא לדון עליו כי אינו צריך עינוי, ומה גם לאשר קדם לנו כי נזדכך גופו ודמי לבר אלהין מלאך ד' אין צורך בעינוי, אשר על כן צוה ה' ואמר **והיתה לכם** פירוש מדבר עם משה ואהרן שגם הם בכלל העינוי. וכדי שלא תחשוב דדוקא למשה ואהרן יצוה ה' ולא לכל ישראל תלמוד לומר **האז רח והגר**, ובסמוך יתבאר באופן אחר:
@29 **לחקת עולם**. טעם אומרו **עולם**, לצד שתבא הסברא שלא בא העינוי אלא לכפר עון ומעתה כל שאין רישומו של עון במציאות בישראל אין חיוב בעינוי לזה אמר **חקת עולם**, ופנימיות הדבר הוא חוקה של עולם הבא, והוא סוד נכמם:
@29 **תענו את נפשותיכם**. פירוש עינוי הכולל לנפש בהשואה ואיזה זה מניעת המזון, ואם אתה אומר שיענה עצמו במלאכה ישתנה הדבר בב' דברים, הא' שמתענה ביותר החלק ממנו הטורח באותה מלאכה ואם כן אין עינוי הנפש בהשואה והתורה אמרה תענו את נפשותיכם, הב' כי בסדר זה יקרא עינוי הגוף כי הבשר החי מתיגע והתורה אמרה נפשותיכם ומעתה תם לריק כחם של הקראים:
@29 **האזרח והגר**. בתורת כהנים אמרו וזה לשונם האזרח, אזרח זה אזרח, האזרח לרבות נשי אזרח, גר זה הגר, הגר לרבות נשי הגר, בתוככם לרבות נשים ועבדים ע''כ. ועדיין צריכין אנו למודעי למה הוצרך לזכרון אזרח, ואם בשביל ריבוי ה''א המרבה נשים, זה טעות כי יש לאלוה מילין לדבר באופן שירבה הצריכין להתרבות מבלי תוספות אפילו אות אחת ללא צורך. ויתבאר הענין על פי מה שאמרו במסכת סוכה (כח:) וזה לשונם אמר מר האזרח לרבות הנשים לעינוי יום כיפור אמר רבא מדרבי יהודה אמר רב נפקא דאמר רבי יהודה אמר רב השוה הכתוב אשה לאיש לכל עונשין שבתורה ומתרץ לא נצרכה אלא לתוספת עינוי סלקא דעתך אמינא הואיל ומיעט רחמנא לתוספת עינוי מעונש ואזהרה לא יתחייבו נשים קמ''ל ע''כ, ועל פי הדברים האלה יש טעם בדבר שהוצרך הכתוב להזכיר אזרח, לצד שהרבוי ה''א על התוספת עינוי, לזה נתחכם ה' וזכר שניהם יחד המתרבה ורשימת דבר שבו מתרבה, והוא אומרו **האזרח** פירוש אזרח זה אזרח שחייב גם בתוספת עינוי כרשום במקום אחר ודומה לו הוא המתרבה בתיבת ה''א ואין חילוק ביניהם. ואחר שהוכרח לומר האזרח לטעם האמור חש שיטעה הטועה לומר שאומרו האזרח הוא למעט הגר שאינו בגדר זה של מצות יום כיפור תלמוד לומר **הגר**, ואם היה אומר גר לבד בלא ה''א היה לבעל הדין לחלק חילוק נכון כי נשי הגר לא שהרי הכתוב חלק בין ישראל לגר שבישראל ריבה הנשים ובגרים לא ריבה, לזה הוצרך לומר הגר לרבות נשי הגר. עוד נראה ליישב טעם הכתוב שהוצרך לפרט כל הפרטים לצד שהוצרך לפרט הכהנים כמו שפירשנו בתיבת לכם מעתה חל עליו לפרט גם האזרחים לבל יבא הטעות כי לכהנים לבדם יצו ה', ואחר שכן חל עליו לפרט כל הנרמזים בפרשה:
@34 **והיתה זאת לכם וגו'**. מקרא זה חוזר אל הכהנים לקיים לדורות מצוה האמורה בתחילת הפרשה שהיא עבודת כהן גדול, לבל יחשוב שלא נאמרה אלא לשעה תלמוד לומר **זאת לכם לחוקת עולם**, **לכפר על בני ישראל** כאן גילה ה' סודו כי על הכהנים ידבר כי הם המכפרים. עוד נתכוון בזה לבל יאמר אדם שלא צוה ה' לבל יכנם בבגדי זהב אלא בעת ההיא פעם ראשונה שעדיין לא נתכפר רושם עון עגל זהב אבל מפעם ראשונה ואילך כבר נמחה ונמחק רישומו ובא יבא אהרן בבגדי כבוד אל הקודש פנימה תלמוד לומר **והיתה זאת לכם לחוקת עולם** בלא שינוי, וגמר אומר **לכפר על בני ישראל**, אולי שנתכוון לתת טעם על הדבר לומר שהגם שבבחינת אהרן לא נשאר רושם מהעגל כיון שבערך ישראל לשמצה בקמיהם לא נמחק רושם העגל כל עיקר, ומעתה מתעגל הדבר גם על אהרן:
@34 **ויעש כאשר צוה ה' וגו'**. רז''ל אמרו (תו''כ) כי הכתוב יכוין להגיד שבחו של אהרן שלא עשה לגדולה ולהתנשא אלא עשה הכל לקיים מצות ה'. ונראה כי גם שבחו של משה יגיד שהרי ה' לא דבר עם אהרן אלא עם משה, והתורה מעידה שלא נשתנה הדבור לצד אמצעיות האמצעי, הא למדת שהדברים הנאמרים מפי משה לא נולד בהם השתנות אפי' בחלק מס' מחוט השערה, וזה בנין אב לתורתינו הקדושה שכולה היא מוצא פי ה' יחיה האדם חיי עולם בהגיגו בנועם עליון:
@37 **איש איש וגו' אשר ישחט**. טעם כפל איש איש. בזבחים (קח.) דרשו אליבא דרבי שמעון לרבות השוחט להדיוט שחייב וכאילו אמר איש לאיש, ולא דרשו לרבות שנים ששחטו משום שאמר הכתוב לאיש ההוא ונכרת האיש ההוא, ודרשו תיבת ההוא אחת למעוטי מוטעה ואנום ושוגג, ואחד למעט שנים ששחטו על זה הדרך ההוא ולא הם וקשה שבתורת כהנים דרשו למעט שנים ששחטו מדכתיב דם שפך ולא מתיבת ההוא. ויש לומר כי להיות שיש ב' מיעוטים ההוא ושפך ודרשו בתורת כהנים מיעוט אחד לשוגג ואנוס ומוטעה ומיעוט א' למעט שנים ששחטו אינו מקפיד הש''ס להמציא מיעוט שני' ששחטו מושפך או מההוא, ועיין בפסוק שאחר זה:
@37 **אשר ישחט**. בתורת כהנים אמרו וזה לשונם אין לי אלא וכו' מנין לשוחט עוף תלמוד לומר או אשר ישחט, והלא דין הוא ומה שחיטה וכו' מליקה וכו' אינו דין וכו' תלמוד לומר אשר ישחט על השחיטה הוא חייב ואינו חייב על המליקה ע''כ. משמע כי מתיבת או מרבה שחיטת עוף ומאשר ישחט ממעט המליקה שהיתה באה בקל וחומר. וקשה מברייתא שהביא במסכת זבחים (קז) מוכח כי רבי ישמעאל דורש מאשר ישחט לרבות שחיטה לעוף וממה שאמר הכתוב זה הדבר מיעט המליקה שהיתה בא בקל וחומר. וגם לרבי עקיבא שחולק שם עם רבי ישמעאל דורש ריבוי שחיטת העוף מדם יחשב ומיעוט המליקה מאשר ישחט כדמוכח מהש''ס שם, ואם כן ברייתא של תורת כהנים לא רבי עקיבא ולא רבי ישמעאל. והנה בהכרח לומר כי ברייתא של תורת כהנים אינה כר' ישמעאל ממה שדרש שם זה הדבר לגזירה שוה מה זה הדבר וכו' אל ראשי המטות וכו' אם כן בהכרח שלא כרבי ישמעאל, גם ממה שלא דרש בתורת כהנים יתור דם יחשב לדרשת רבי ישמעאל לרבות הזורק אם כן מוכח שדורשה כרבי עקיבא, גם ממה שדרשו בפ' י' או זבח לרבות הדם כדברי רבי עקיבא בברייתא שהביא בש''ם דזבחים, הרי זה מראה באצבע כי דרשת תנא דתורת כהנים הוא כדרכו של רבי עקיבא, ומעתה תהיה דרשת שחיטת עוף מדם יחשב ומיעוט מליקה מאשר ישחט ולמה דורש תנא דתורת כהנים ב' הדרשות מאו אשר ישחט, ועוד לתנא דתורת כהנים שדורש ב' הדרשות מאו אשר ישחט דם יחשב שאמר הכתוב למה לי:
@37 **וראיתי** להרמב''ם ז''ל שכתב בפרק י''ח מהלכות מעשה הקרבנות וזה לשונו שנים שאחזו בסכין ושחטו פטורים שנאמר אשר ישחט או אשר ישחט אחד ולא שנים ע''כ. וקשה להרמב''ם ז''ל למה עשה לימוד חדש ולא רשם הלימוד שהוזכר בברייתא ובתלמוד. ועוד קשה להרמב''ם ז''ל והרי פסוק אשר ישחט אשר ישחט דרשוה למשפט העוף בין לתנא דתורת כהנים בין לרבי ישמעאל בין לרבי עקיבא שהובא דבריהם בזבחים שכתבנו למעלה אשר ישחט אצטריך ללמד על העוף למר לרבות שחייב על שחיטתו ולמר למעט המליקה, ודין זה פסקו רמב''ם בסוף פרק י''ט מהלכות מעשה הקרבנות ועוד קשה למה שכתב הרמב''ם חיוב לשוחט לאיש מפסוק דם יחשב לאיש ההוא דם שפך, שכתב וזה לשונו אף על פי שלא נתכוון לשחוט קדשים אלו לה' הרי זה חייב שנאמר דם יחשב וגו' דם שפך אף על פי שזה הדם במחשבתו כדם הנשפך לא כקרבן הרי זה חייב ע''כ, והרי הש''ס דורש חיוב שוחט לאיש מאמרו איש איש ועוד דם שפך דרשו בתורת כהנים למעט ב' ששחטו או למעט אנוס שוגג מוטעה כמו שכתבנו למעלה ומה מקום לדרוש ממנה שוחט לאיש. והנה דרשה זו אמרוה בזבחים דף ק''ח ע''ב אליבא דרבי יוסי שחולק על רבי שמעון בדרשת איש איש, ולזה יש לומר שבחר הרמב''ם להביא הראיה מיתור דם שפך שהיא יותר חזקה מדרשת איש איש שאינה דרשה חזקה. והראיה ממה שאמרו במסכת מציעא (לא.) בפסוק העבט תעביטנו שסובר רבי שמעון דברה תורה כלשון בני אדם, וכתבו התוספת שם כי במקום שיש איזה הוכחה הפך דרשה הנשמעת מכפל הדברים אנו דורשים כפל התיבה ואין אנו אומרים דברה תורה כלשון בני אדם וכשיש התנגדות לדרשת הכפל אנו אומרים דברה תורה כלשון בני אדם, מעתה אין דרשת כפל איש איש חזקה כדרשת דם שפך שהביא הש''ס אליבא דרבי יוסי, והגם דהש''ם לא קאמר לה אלא אליבא דרבי יוסי, אף על פי כן ממנה נקח לרבי שמעון כי אין הכרח לעשות מחלוקת ביניהם בזה, והגם דהש''ס קאמר לסברת רבי שמעון שדורש שוחט לאיש מאיש איש, זה היה קודם שידע דרשת דם יחשב וגו' דם שפך מה שאין כן אחר דרשה זו הוא דבר השוה לכולם, ולזה כתב הרמב''ם מדרשת דם שפך, אבל קושיתינו הראשונה לדברי רמב''ם במקומה עומדת:
@37 **ונראה** לומר דסובר רמב''ם כיון שאנו רואים כל כך שינויים בין ברייתא של תורת כהנים וברייתא שהביא הש''ס בזבחים ובין דברי הש''ס גם כן כמו שכתבנו למעלה, אם כן מוכיחים הדברים שאין להקפיד על שינוי מקום דרשות אלו, ולזה למה שמוכיח רמב''ם מפסוק דם שפך שוחט לאיש דחייב אם כן אין לנו מנין לדרוש מיעוט שנים לזה חפש אחר דרשות יתור אשר ישחט שהיא מיותרת ואין אנו דורשים שחיטת עוף אלא מתיבת או, וכמו שדרשו בתורת כהנים שמרבה שחיטה לעוף מאומרו תיבת או לרבות ולפי זה דרשינן מיעוט מליקה בעוף מאומרו זה הדבר למעט מליקה בעוף וכדברי רבי ישמעאל שכתבנו למעלה שדורש מיעוט מליקת עוף מזה הדבר. ולא יקשה לך ממה דקיימא לן (ערובין מו:) הלכה כרבי עקיבא מחברו, כי אין בזה הפך רבי עקיבא בענין הלכה:
@39 **זבחי שלמים לה' וגו'**. היה צריך לומר וזבחו אותם זבחי וכו', ואולי שנתכוון האדון להראות חיבת הקודש אשר חבב עמו, ואמר **כי זבחי שלמים** הם קרבנות המשתתפים בשולחן אחד יחד בנים ואביהם, והוא אומרו **שלמים לה' אותם**, וחוזרת תיבת אותם לבני ישראל הזובחים האמורים בתחלת הכתוב לא לנזבחים.
@39 ועל דבר זה לבד תתנתק הנפש מנרתקה ותקום לעבודת האל במסירת נפש מבלי הרגש להפלגת עריבות הנרגש בבחינת אהבתו יתברך בנפש המרגשת בטעימת נועם חיבתו, וכל זה קטן הוא להמתחייב לנו עשות לערך המוקדם ממנו יתברך בבחינת שעשוע חיבובינו ורוממות אשר רומם עם קדושו:
@42 **ואליהם תאמר וגו'**. במסכת זבחים (קז.) תניא ר' ישמעאל אומר לעירוב פרשיות לומר שאף שחוטי חוץ שהעלה בחוץ הגם שאין ראויים לפנים כגון השוחט בפנים ומעלה בחוץ דתניא במשנה תחלת פרק י''ג דזבחים. וליתן כל האמור של זה בזה זולת דברים שריבה הכתוב באחד מהם ומיעט בחבירו. ועיין בדברי רש''י בזבחים:
@42 **איש איש וגו'**. עיין בפסוק שלפני זה:
@42 **מבית ישראל**. הוצרך לומר מבית ישראל ולא הספיק במאמר ואליהם שממנו מובן שחוזר להאמורים למעלה מהענין. לצד שאמר איש איש לומר שנים ששחטו כמו שכתבתי בסמוך, וחש הכתוב שיבא הדורש וידרוש לרבות הגוים כמו שדורשים (מנחות עג) באיש איש האמור בנדרים ונדבות (אמור כב יח) שהוא לרבות גוים, לזה הוצרך לומר מבית וגו' דוקא ישראל ולא אומות וממילא נתחייב לדרוש באיש איש כל מה שדרשו ז''ל. ואחר שהוצרך לומר מבית ישראל חש הכתוב לומר שמיעט הכתוב הגרים תלמוד לומר ומן הגר, והוצרך לרבות כל הריבוים דזולת זה יאמר האומר שלא ריבה אלא מה שהזכיר בכתוב. וגם לדעת ר' יוסי שסובר דברה תורה כלשון בני אדם. אולי שלא אמר כן אלא לצד שיש לו מניעת הדרשה בו לצד מיעוט ההוא. והגם שהקשה הש''ס לר''י דכיון שאינו דורש איש איש שבפרשה ב' גם איש איש שבפרשה א' לא ידרוש, אין הכי נמי אם לא היה הש''ס מוצא דרשות דם שפך היה אומר שדורשה מאיש איש, שכל שאין נגדיות לדרשה לא אמרינן דברה תורה וכו', ועיין בדברי התוספת במציעא דף ל''א ד''ה דברה תורה כלשון בני אדם שאין סברא לומר דלית לתנא כמה דרשות שנדרשו בכפל, והגם שהתוספת פרטו הקושיא לרבי שמעון על כל זה ישנה לכל. ועיקר מחלוקת התנאים היא בסברא בדבר המתנגד לדרשה שכפי הסברא מטה לומר דברה תורה כלשון בני אדם ותמצא שגם רבי שמעון מצינו שאמר (ב''מ לא:) דברה תורה כלשון בני אדם ומצינו לו שדורש הכפל:
@44 **ואיש איש וגו' אשר יאכל וגו'**. טעם כפל איש איש, בתורת כהנים דרשו וזה לשונם ישראל אלו ישראל, גר אלו גרים, הגר לרבות נשי הגרים, בתוכם לרבות נשים ועבדים, אם כן למה נאמר איש איש אמר רבי אלעזר ברבי שמעון להביא ולד ישראל מן הגר ומן העבד ע''כ. צריך לדעת למה הוצרך הכתוב לפרט כל הפרטים, וכדרך שהקשו במסכת סוכה (כח) באותה ברייתא שאמרה האזרח לרבות הנשים וזה לשונם מדר' יהודה אמר רב נפקא דאמר ר' יהודה אמר רב השוה הכתוב אשה לאיש לכל עונשים שבתורה ותירץ שם שאיצטרכא לתוספת עינוי וכו' ע''כ. אם כן גם במה שלפנינו יש להקשות כן למה הוצרך לרבות הנשים וכו' בין נשי ישראל בין נשי הגר. עוד יש לנו לעמוד על כוונת דברי התנא מה הוא הולד ישראל הבא מן הגר שהוצרך הכתוב לרבות מאיש איש, אם הוא המיר כבודו מגירות והלך לחרפות, הרי הוא גוי ולמי בא הכתוב להודיע האיסור. ועוד התנא אומר בפירוש ולד ישראל משמע שביהדותו עומד, אם כן פשיטא שלא גרע מגר שאמר קרא בפירוש ולמה איצטריך איש איש, והרב בעל קרבן אהרן כתב שגרסינן בברייתא מן הגוי ומן העבד, וירצה ולד בת ישראל הבא מן ע''ג או עבד שאף על גב שאביו עכו''ם או עבד שלא הוזהרו על הדם וכו' מחויב אם אכל דם דגריר אחר אמיא וכו' דגוי ועבד הבא על בת ישראל הולד כשר כדאמרינן ביבמות (כג.) בנך הבא וכו' קרוי בנך וכו' ע''כ. וקשה לי כיון שהכתוב קראו לזה בן ישראל אם כן ישראל גמור הוא, ואם מדבר הכתוב בבן שלא רצה לעמוד ביהודת אמו אם כן פקו פליליה ולמי בא הכתוב להודיע תורת ה'. ואם לכופו על הדבר ממה נפשך אם ביד ישראל לכופו פשיטא שכופין אותו כדין כל איש ישראל שעובר על התורה ואם אין בידינו לכופו הרי אין ברשותינו, ואם כן קרא למאי אתא:
@44 **ונראה** לומר בהקדם לדעת טעם איסור זה, כפי מה שהאירו חכמים את עינינו בפנימיות התורה, כי כל נפשות עם בני ישראל הם ממדריגה שאין למעלה ממנה בסוד (דברים לב ט) חלק ה' עמו. גם אמרו שהגם שהם בעולם התחתון ורחוקים ממקום גבוה אף על פי כן ישנם דבוקים בחוט של חסד עד מקום שורשה בסוד אומרו (שם) יעקב חבל נחלתו, ונפש הבהמה היא ממדריגה התחתונה אשר יתיחם מקומה אל קליפת נוגה והנה באכול אדם מדם בהמה שהנפש יוצאה בו שעליו בא עונש כרת קונה נפש הבהמיית מקומה בנפש אדם. והדיענו הכתוב כאן כי האוכל דם ומכניס נפש הפחותה בנפשו יגעל אותו שורש העליון לבל יהיה עוד נדבק בו. והוא מאמר **ונתתי פני בנפש האוכלת את הדם והכרתי אותה מקרב עמה** פירוש שיכרות החוט הקשור בשרשו שהוא מקור כללות נפשות עם ה', והוא אומר מק **רב עמה**. עוד ידוע הוא כי הגם שבכללות עם ישראל שורש אחד אף על פי כן הם במדריגות זו למעלה מזו בסוד (קהלת ה) כי גבוה מעל גבוה וגו'. וכיון שכן תבא הסברא לומר לצד שהנפש בהמה זו לא טמאה היא שהרי היא בהמה טהורה הנאכלת לזה לא תעשה נפש הלזו פגם ודופי אלא דוקא בהדרגה הגדולה שבישראל, ועונש שיחד ה' לעבירה זו אינו אלא להאזרחים זכרים ולא נקבות, וכשירבה הכתוב איזה ריבוי אין לנו בו אלא חידוש הדרגה אחת עד שירבה קצת המדרגות, גם כלך לדרך אחר יש לומר שאין הפעולה הלז עושה כל כך רושם להצטרך לכורתה אלא נפש שהיא קלת הערך אבל נפש רמה אפשר שהגם שתעשה בו רושם אף על פי כן לא תעשה כל כך פעולה בה כדי שתצטרך לכרת. אשר ע''כ נתחכם אל נורא עליל' וריבה כל הריבוים ואמר כי קטן וגדול ישנו בהכרת באוכלו דם הנפש, ואמר ריבויים לכל ההדרגות קטן וגדול:
@44 **והנה** לפניך ההדרגות זו למעלה מזו, ראשון שבקדושה זכרי ישראל ב' נשיהם לצד שהאשה אינה במדריגת האיש, ג' גר הבא מישראל וגיורת, ד' גר הבא מגר וישראלית, ה' גיורת כיוצא בשני ההדרגות, ו' גר הבא מגר וגיורת, ז' גיורת הבא מגר וגיורת, ח' גר עצמו, וכל אלו ההדרגות באו בכתוב, ראשון שבקדושה ישראל הזכירם בפירוש והוא מאמר תנא של תורת כהנים ישראל אלו ישראל. והזכיר הגרים ב' פעמים, וב' ריבויים עמהם הגר הגר. ותמצא שבמסכת סוכה (כח) דרשו ה' של האזרח לרבות נשיהם, נמצאת אומר כי ה''א של הגר הגר ריבויים הם, הרי לפניך ד' ריבויים בגרים והם כנגד ב' הדרגות שבגרים הא' הוא הגר שנולד מגר וגיורת והב' הגר עצמו שנתגייר, ושני הריבויים כנגד נשיהם שבהדרגתם, ואולי שלזה דקדק ואמר תנא דתורת כהנים הגר אלו הגרים ולא אמר זה גר שנתכוון לב' הדרגות דגרים כאמור, וא' הגר לרבות נשי הגרים פירוש מריבויי ה''א נתרבו נשיהם, ואמר **בתוכם** לרבות נשים ועבדים כמאמר התנא פירוש נשים אזרחיות ועבדים שדינם שוה לנשים, ולא תקשה למה הוצרך לרבות' והלא קל וחומר מגרים, ואין לומר שהייתי אומר כי לצד שהם גדולים מערך גר יצטרך לומר כי גם בהם יפעיל הכרת כמו שאמרנו בטעם זכרון ישראל, כי אחר שהוזכרו זכרי ישראל מכל שכן הנשים הנה אם לא היה ריבוי בתוכם שריבה בה קרא נשי ישראל לא היינו מרבים מה' של הגר ב' גיורים כמו שאמרנו, הרי לפניננו ו' ריבויים, ואמר **איש איש** ב' ריבויים אחרים ודרש אותם תנא בתורת כהנים ואמר להביא ולד ישראל הבא מן הגר ומן העבד פירוש ולד ישראל שיש בו זרע ישראל ובא גם כן מן הגר והוא אומרו מן הגר, והכונ' היא שאביו ישראל ואמו גיורת או אביו גר ואמו ישראלית, ושני הדרגות אלו נדרשים מכפל **איש איש**:
@44 **ולא** תקשה למה הוצרך הכתוב לרבות ההדגרות אלו אחרי שכבר ריבה גר גמור כמו שאמרנו, כי אם לא היה ריבוי איש היינו מפרשים דגרים האמורים בבאו מישראל וגיורת או מגר וישראלית. ומעתה הקדים הכתוב הדרגה החשובים שבגרים שיש בהן חלק ישראל ואחר כך אמר הגר הגר שכולן גרים, הרי לפניך ח' ריבויים. ואם תאמר גיורת הבאה מישראל וגר מנין, יש לומר שלאחר שנתרבה אפילו גר עצמו שנתגייר פשיטא שאין להפחית ממנו גיורת הבאה מישראל וגר הגם שהיא נקבה, ולדרך זה תתהלך בכל מקום שירבה ריבויים כאלו:
@44 **בנפש וגו'**. בתורת כהנים דרשו ולא בציבור ע''כ. הטעם כי אין כח בעון זה להכרית ציבור. ועיין במה שפירשתי למעלה:
@44 **מקרב עמה**. בתורת כהנים דרשו ועמה בשלם ע''כ, ואין ידוע הכוונה בזה, ממה נפשך אם חייבים מדין ערב למה יהיו פטורים כאן, ואם אינו מדבר במי שחייב מדין ערב כגון שלא ידעו או נאנסו אין צריך לומר. ונראה כי יכוון לומר כי כריתת הענף הרע מהאילן משביחו כידוע, ולזה אמר מקרב עמה פירוש כדי שלא יזיק ענף הרע לנצר מטעיו יתברך יכריתהו וישאר עמה בשלם:
@45 **כי נפש הבשר וגו'**. צריך לדעת נתינה טעם למה חוזר זה, ולפי מה שפירשתי למעלה הן הן הדברים שכתבנו שנותן הטעם למה תכרת נפש האוכלת, לצד שיש בדם הנפש והוא נותן בתוכו נפש הבהמית. אלא שעדיין יש לנו לחקור למה אמר נפש הבשר ולא אמר כי הנפש בדם. ונראה שנתחכם ה' להשיב לשואל למה לא אסר גם הבשר כי גם בו היה חיות הבהמה וכשאדם אוכלו יגרום הפגם בנפשו, לזה אמר וכי נפש הבהמי היתה בבשר, לא כן הוא, לא היתה אלא בדמו של בשר והדם הוא מחיה הבשר. ואין הנפש בבשר כל עיקר כאומרו **נפש הבשר בדם** היא הנפש ולא בבשר. ותכונה זו לא הכינה ה' בתכונת אדם כי האדם התפשטות חיונותו היא גם בבשר וגם בעצמות, ונקרא בדבריהם הבלה דגרמי שנשאר אחר כמה שנים בעצמות, ולזה אינם נרקבים הצדיקים, ויש רשעים שנמשלו כבהמות והן הנה שאינם עומדים בתחיית המתים לצד שיבשו עצמותם ונרקבו וכלתה הנפש והלכה לה כרוח הבהמה:
@45 **ואני נתתיו וגו'**. פירוש ותדע שהדם הוא הנפש שהרי אני נתתיו לכם וגו' לכפר על נפשותיכם נפש תחת נפש הרי כי הדם הוא הנפש. עוד יכוון הכתוב להזהיר על נפש הבהמה לבל המיתה, כי לא נתן ה' דם הבהמות לנו אלא לכפר על נפשותינו, והוא אומרו **נתתיו לכם על המזבח** לשלול זולת סיבה זו שאינו לנו במתנה לעשות כל אשר נחפוץ עשות בו. ותמצא (סנהדרין ב.) שדין הריגת בהמה צריך שיהיה על פי בית דין של כ''ג כמשפט אדם שהשוה הכתוב משפטם למשפט אדם, ולא הותרה בהמה לשחוט אלא לצרכי בשרה כי תאוה נפש אדם לאכול בשר שכן גמר קונה עולמו והקנה לנו דכתיב (ראה יב כ) כי תאוה נפשך לאכול בשר בכל אות וגו':
@47 **אשר יצוד ציד וגו'**. צריך לדעת לאיזה ענין הוצרך הכתוב לכתוב כל זה שלא היה לו לומר אלא איש אשר ישחט חיה או וגו' או אשר ישפוך דם וגו'. עוד אם גזירת הדברים היא מצות הכיסוי היה לו לומר יכסהו בעפר כי אומרו וכסהו משמע שקדמה מצוה אחרת. ונראה כי באמרו **אשר יצוד** נתכוון לאסור צידת מין טמא לכתחלה, הגם שהתירו הכתוב בהנאה, וכמו שהעליתי בספרי פר''ת סי' קי''ז כדעת רמב''ם (מ''א פ''ח) שאין התר' לצודם אלא אם מתכוון לצוד טהורים ונזדמנו עמהם טמאים, והוא מאמר הכתוב כאן **אשר יצוד** וגו' תנאי הוא הדבר שאין מתיר לו לצוד אלא **אשר יאכל** ולא אשר לא יאכל ואמר **וכסהו** לצד שקדם מצוה אחרת שלא לצוד שלא יאכל יוצדק לומר וכסהו בתוספת ו', ואמר **ושפך** וגו' פירוש שאסור לאכלו כדרך שאמר במקום אחר (דברים יב טז) לא תאכלנו על הארץ תשפכנו כמים, ולזה גמר אומר כאן ואמר **כי נפש כל בשר** וגומר **ואומר** וגו' הא למדת כי נתכוין במאמר **ושפך** לאסור אכילת דם חיה ועוף. נמצאת אומר ג' מצות נאמרו כאן, א' לא יצוד טמאים ליהנות מהם, ב' לא יאכל דם חיה ועוף, ג' מצות עשה לכסות דם חיה ועוף:
@47 **עוד** נראה שרמז באומרו **ושפך וכסהו** שאין צריך לכסות כל דמו אלא חלק בשפיכה וחלק בכיסוי (חולין פח.):
@48 **דמו בנפשו**. פירוש במקום נפשו. ובזה נתן טעם למה צריך לכסות דמו, כי לצד שדמו היא נפשו מהמוסר לנהוג בו כבוד זה כדרך שצוה ה' לקבור אדם מת משום כבודו, וטעם שלא אמר כדרך שאמר בבהמה נפשו בדמו. אולי שהבהמה יש לה נפש והיא נתונה בדם אבל חיה ועוף אין להם נפש כבהמה אלא הדם הוא במקום הנפש, ובזה אינם באים על המזבח לכפר כבהמה זולת תורים ובני יונה, וגם המה אין בדמם הזאה על המזבח אלא מיצוי כשמולק:
@48 **כי נפש כל בשר וגו'**. פירוש לא לצד שהדם מכפר על המזבח הוא שאסרתי הדם שאז תחלק בין דם בהמה לדם חיה ועוף אלא טעם האיסור הוא לצד כי נפש כל בשר וגו', ומעתה גם חיה ועוף בכלל:
@48 **כל אוכליו יכרת**. כבר כתבתי למעלה טעם הכרת. וטעם אומרו **אוכליו** לשון רבים ויכרת לשון יחיד, להעירך על פירושינו שהכרת הוא שיסתלק חיוני' המאיר בשורש נשמתו ונכרת השורש ההוא לזה אמר לשון יחיד. ואמר אוכליו לשון רבים, לצד שהנהנים מהאכילה רבים המה, כי חיוניות הנדבק בשורש עליון יש תחתיו הכנות כדי שיוכל עמוד ביחד עם הגוף, כי הגוף הוא חומר גשם וברא ה' בו כח המניע והוא הנפש שתכונתה היא נוטה על הגשם ויתאו למטעמותיו, ובראם ה' ב''ה בתכונה זו כדי שיתמזג עם הגוף והוא מוכן לבחינת הנשתוה לרוח, והרוח הוא מוכן לנשמה, והנשמה הוכנה להשרות שכינתו על הראויים, ומעתה כשאדם אוכל הדם הרי לפניך אוכלין מרובים, הגוף, הנפש, הרוח, הנשמה, ובבחינת העונש שהוא הכרת אין נכרת אלא חוט הנשמה הקשורה למעלה ובזה יבשו כל הענפים לזה אמר לשון רבים:
@48 **עוד** רצה על דרך מה שאז''ל (תו''כ לעיל ג') כי הציבור אינ' נכרתים בעון אכילת דם, לזה אמר **אוכליו** לשון רבים ויכרת לשון יחיד לומר שהגם שיאכלו רבים אין כרת אלא ליחיד ולא לציבור:
@48 **ונתתי** אל לבי לדעת מה טעם יצו ה' לכסות דם חיה ועוף ולא דם בהמה, בשלמא דם הנזרק על המזבח הוד ותפארת לו מדם חיה ועוף אבל דם שחיטת חולין אשר הוא נופל וגלוי עינים למה תגרע בהמה מחיה, ומה גם למה שמצינו שבחר לו יה קרבן מהבהמה ולא מחיה ועוף זולת תורים ובני יונה, והנה לפי מה שפירשנו שחיה דמה היא הנפש עצמה מה שאין כן הבהמה כי יש נפש מלבד הדם והיא מורכבת בדם ואין דמה עצמו נפשה, לזה לא צוה ה' לכסות הדם אלא הדם שהוא עצמו נפש מה שאין כן הבהמה שאין הדם עצמו נפש כמו של חיה ועוף, והגם שגם בדם בהמה יש נפש בו, על כל זה לא הדם עצמו נפש ואין כיסוי אלא למורגש ולא להיולי הגם שישנו והבן. וראיתי לתת לב משכיל מפני מה נשתנית בריית חיה מבהמה בבחינה זו:
@48 **ונראה** שהטעם הוא לפי מה שקדם לנו בהתבוננות מושכלות השפעות הקיום והעמדת כל יש, כי האל הבורא ב''ה הוא חיות הכל והכין ועשה פעולות כדי שכל הווה יגיענו ההסתפקות מן הצורך לקיומו, וחלק כל בריותיו לד' הדרגות והם אש רוח מים עפר, וכל אחת כלולה מהד'. וארבעה אלו תחלת הווייתה היא נעלמת מעיני כל בשר והיא רוחנית בתכלית הרוחניות והם ד' רגלי כסא כבודו יתברך ונשפעים מהם בכיוצא בהם ד' בריות אחרות נושאי הכסא פני אדם פני נשר פני אריה פני שור וכנגדם ד' מלאכים גבריאל רפאל מיכאל נוריאל אלו הכנה לאלו ומקבלין זה מזה ולעומתם יש למטה מקבלין בבעלי חיים אדם שור נשר אריה אדם מין אנושי שור מין בהמה אריה מין חיה נשר מין עוף וכנגדם בדוממים עפר מים אש רוח וכל א' כלול מארבעתם וגם בבחינת הנשמות שהם בריאה העליונה שבעליונות אשר ברא ה' מאורות עליונות חלק ה' ב''ה כמו כן ימצאון בחינות וחזר הדין שכל נושא ונושא כולל כל זה וכל מדרגה משפעת ונשפעת ממדריגת כסא הכבוד שהיא למעלה מחיות הקודש עד מדריגה הדומם. ומעתה אבוא לראות הנשפעים הנדמים מהד' בחינות הנגלים דוגמתם למעלה והנה יש לו בחינת שור בהמה טהורה הנשפעת מדמות פני שור אבל חיה ועוף לא מצינו בנדמים נשפעים למטה מהמושפעים מהקדושה כי אריה חיה טמאה נשר עוף טמא ויש לחקור זאת למה נמנע הנדמה מהתקבל בחינת הקדושה והטהרה כמו שקבל השור גם מנין נמשכה בחינת הטוהר לשאר חיות הטהורות אשר התירה תורה איל וצבי וגו' דע כי יש הדרגות שאין יכולת המקבל לקבל בתגבורת המשפיע בבחינת בסוד טעם עיני חכמי ישראל כידוע ליודעי דעת בהתבוננות הצודק בשכל ההבחן ולזה לצד כי אריה ונשר שלמטה באו בתגבורת לא יוכלו לסבול שיעור הנתכן והנשער אליהם בתכונת איכותם ולצד חסרון התקבל' השער' ההסתפקות מביחון הנרזב אשר בגן ה' כשיעור הצלחתם מהמקוה אליהם זו סיבה למרחקם אשר צוה ה' לאיש ישראל לבל יקרב אליהם כי איש ישראל הוצלח בנקוה אליו בסוד אומרו (דברים ד) הדבקים בה' ושיעור אשר הגיעו בבחינת אריה נשר כמוהו וכשיעורו נסתעף בקצת מהחיות והעופות ועשה בהם שיעור ההסתפקות והגם שלא בא איכותם אלא על ידי נשר כי הנשפע ראשון זה הוא סוד (איוב יד) מי יתן טהור מטמא וגו' וכל זה עשאו יתברך לסיבה הידועה סוד ה' ליראיו וכיון שכן אין תכונת הקדושה והטהרה המשתלשלת דבחינת הבהמה דומה לבחינת חיה ועוף כי בחינת שור יש דומה לו למעלה במקור הקדושה אשר ברא הבורא ותיכן בו הנפש מה שאין כן בחינת חיה ועוף לצד שנפסק דמות הנדמה למשפיע הנה הוא טמא לפנינו דכתיב (לעיל יא) את הנשר ואת וגו' תשקצו תש כחו ואין בו אלא החיוניות שהוא דם טוהר כאמרו דמו בנפשו וכמו שפירש דמו במקום נפשו זולת תורים ובני יונה שיודע אל עליון שגבר בהם החיונים וממוזגים הם בין הבהמה והעוף שמביאים מהם קרבן עולה וחטאת דוקא ויחיד דוקא ולא ציבור וצריך כיסוי כי עד גדר הבהמה לא בא כל זה כתבתי עם חפץ ד' והמשכיל ישכיל דבר אלהים חיים:
@49 **וכל נפש אשר תאכל נבילה**. אמר **וכל נפש**, לכלול כל המתרבים למעלה (פסוק י) ח' הדרגות כמו שפירשנו, והזכיר ב' הדרגות כלליות אזרח וגר, ודקדק לומר **באזרח ובגר**, פי' כל שנכלל באזרח וכל שנכלל בגר:
@52 **דבר ואמרת וגו' כמעשה וגו'**. צריך לדעת למה כפל לומר **דבר ואמרת** עוד מה חידש במאמר זה **אני ה' אלהיכם** וכי עד עתה לא ידעו זה. ועוד מה היא כוונתו במצות כמעשה וגו' אם אין ידוע מה המעשה שעליו תבא המצוה, וכמו כן מעשה ארץ כנען. ורז''ל אמרו (תו''כ) שהקיש מעשה מצרים למעשה כנען ולדבריהם ז''ל קשה למה כפל המצוה, ואם להשמיענו בא שמעשה ב' הרשעים שוה, מה צורך לתורה להודיענו דבר זה עוד צריך לדעת למה ציין ארץ מצרים באומרו **אשר ישבתם בה** וכי יש ארץ מצרים אחרת. עוד ציין **ארץ כנען** ואמר **אשר אני מביא** וגו' שנראה שיש אחרת ולא ידענו זולת זו, ולו יהיה שתהיה ארץ כנען אחרת כיון שאינה ידועה מנין יהיו מעשיה נודעים לצוות עליהם:
@52 **ונראה** כי לפי מה שהסמיך למצוה זו מצות העריות, גם ממה שאמר בסוף הפרשה (פסוק כד) אל תטמאו בכל אלה וגו' כי בכל אלה נטמאו הגוים הדברים מוכיחים ומגידים כי מעשה ארץ מצרים כמעשה ארץ כנען הוא מעשה עריות ובזה נבא לפרש הכתוב על נכון. הנה ידוע הוא כי כל מצות אשר צוה ה' לעם קדושו הם מצות שיכול האדם לעמוד בהם ויטה עצמו אל הרצון לעשותם, זולת מצות פרישת העריות הוא דבר שנפשו של אדם מחמדתן ואונסתו עליהם לעשותם, זולת בהתעצמות הרחקת ב' דברים מהאדם, והם מרחק הרגש ראות העין, ומרחק בחינת החושב, ואם ב' אלו לא יעשה אין אדם שליט ברוח זה לכלותה ממנו, כי כל שלא תהיה לו הרחקת הרגש הראות בדבר הגם שירחיק בחינת החושב לא ישלוט בעצמו לכלות ממנו הכרח החשק. וצא ולמד (קדושין פא.) ממעשה של ר''ע רבן של חסידים שהגם היותו מושלל מבחינת החושב נתנצח מבחינת הראות, גם ממעשה רבי מתיא ב''ח (ילקוט שמעוני פ' ויחי) שבחר לסמות עיניו למיחוש הכרחה אשר מהם תבא בדבר הרע הגם שהיה מושלל מבחינת החושב כאשר מעשיו מוכיחות. גם אם יושלל מבחינת הראות אם לא ירחיק בחינת החושב מחשבותיו יחייבו לבקש ולהתלהט אחר המעשה. וצא ולמד ממעשה שהובא בש''ס (ע''ז כב:) באותו גוי שקנה ירך בשר וחטט בו כדי וכו' ובעל וכו' ע''כ. וזהו יהיה תולדות החושב הכריחתו עשות מבלי בחינת הראות. נמצאת אומר שבא' מהב' תהיה מושללת מהאדם שליטה בעצמו בדבר זה ואין צריך לומר בהצמד ב' דברים ראות וחושב הן האדם חלוש כנגד תאותו, ואין צריך לומר אם ישלח ידו ואכל מעט מן הרע הזה הנה הוא מסור ביד תאותו. מעתה תחבולות האדם להעריך מלחמה נגד בחינה זו היא בשלילת ממנו ב' דברים ובזה תהיה נרכבת באדם תכונה לבל יתלהט אחר זה וישלוט הרצון בחפץ הטבעי והוא טעם אמרו ז''ל (ברכות לד:) במקום שבעלי תשובה עומדים אין צדיקים גמורין יכולין לעמוד, כי הצדיקים גמורים תכונת רצונם נוצחת החפץ מבלי צורך התעצמות מה שאין כן בעלי תשובה:
@52 **ובזה** נבא אל הביאור הנה האדון ה' צבאות נתחכם בצוותו מצוה זו ודבר נגד יצר הרע, שיאמר איך יכול אנוש טבעי למשול בתאותו אשר היא אנסתו דבר זה הוא מושלל מהדעת שיחייב ה' שמירתו לכל בהשואה אלא לאנשים אשר יכולין לעמוד ויש כח ברצונה לשלול החפץ בזה והם אותם שלא באו לידי מבחן הראות והחושב באלו וכדומה דבר הכתוב אבל במי שעברו בחינה הנזכר כפי הטבע אין אדם שליט ברוחו למנוע מעצמו חשק המכריחו, ועל זה נתכוון ה' בנועם דברי אלהים חיים ואמר **כמעשה ארץ מצרים אשר ישבתם** פירוש הגם שישבתם במקום שאנשיה בני זנונים ולא תמנע מכם בחינת החושב לצד ישיבתכ' ביניהם כל הזמן ההוא כאומר **אשר ישבתם בה** ואין ישיבה אלא עכבה וזה יסובב תגבור' החפץ בכם אף על פי כן אנכי מצוה אתכם שתתעצמו לנצח החשק לבל תעשו כמעשיהם, ואמר עוד **וכמעשה ארץ כנען** וגו' **אשר אני מביא אתכם שמה** וגו' פירוש אף על פי שאתם באים למקום אשר שם הרגיעה שידה של בחינת הרע הזה ונמצא בחינת החושב מתעוררת אף על פי כן מחייב אני אתכם לבלתי עשות כמעשיהם. ולצד שיאמר אדם כי אין מעצור ברוחו בדבר זה, לכן הקדים ה' בתחלה דברו הטוב ואמר **דבר אל בני ישראל ואמרת אליהם אני ה' אלהיכם**, כי הן אמת במין אנושי זולת ישראל ישנו בטענה זו כי לא ימצא בכחו למנוע עוצם חשקו ממנו מה שאין כן אתם בני ישראל לצד היותי ה' **אלהיכם** והיא השגה אלהות בכח האלהי ינוצח כח הטבעי גשמי, כי הצורה תשלוט בחומר כשיסכים איש ישראל להתדבק בה' אלהיו ישלוט בטבעו, והוא כמאמרם ז''ל (ב''ר פל''ד) שאמרו הצדיקים לבם מסור בידם והרשעים הם מסורים ביד לבם. הכוונה בזה כי החפץ והחשק ישנו בלב האדם והרצון הוא במוחו והם ב' מדריגות שנתן האדון בבני אדם וכשתזדמן לאדם דבר ערוה הלב חומדה ואין גמר בחימוד זה ויכול הרצון התלוי במוח למנוע החפץ ולא יעשנו הגם שיחמוד, הלא תמצא בבני אדם שמקבלים תענית הגם שהחפץ יתגבר בהם לאכול יבא הרצון וימנענו וכן עז''ה, וצדיקים תמיד מתנהגים כסדר זה ולבם מסור בידם שהגם שיתאוו תאוה בלבם יבחר השכל שהיא הנשמה ואם ישנו באזהרה מה' או מכללי התיעוב ישלול הרצון בו וימנע החפץ הגם שישנו, אבל הרשעים הם מסורים ביד לבם לכל אשר יבא החפץ בלב לא ימנעהו הרצון, ואולי כי אין להם נשמה או שכבר פגמוה ונכנעת היא לפני הרוח שבלב, ולכן אמר ה' **כי אני ה' אלהיכם** פירוש להיות שבחינת הנשמה בה ה' משרה אור שכינתו באדם בסוד (תהלים עח) אהל שכן באדם ומצד זה יש כח באדם לנצח החפץ לפני הרצון:
@52 **והוא** מה שנתכוון לומר דוד המלך עליו השלום במה שאמר (שם מ) לעשות רצונך אלהי חפצתי ותורתך בתוך מעי, הכוונה היא שמרוב דביקתו באדון האדונים יתברך שמו לעד עד שגם הלב נתהפך לעשות כמעשה הנשמה, שבא החפץ בו והתאוה לעשות רצונו יתברך, שאינו מהכת החפצים דברים המרוחקים מהקדושה וצריכים למונעם בשלילות הרצון, אלא שמעצמו חפץ ברצונו יתברך לשנוא דברים אשר הלב חפץ וחושק בהם. והוא מה שדקדק לומר חפצתי כי אפס חפץ המרגשת, וזה אמר במקום אחר (שם קט) ולבי חלל בקרבי, ואומרו ותורתך בתוך מעי פירוש לרוב חשק עבודת הקודש עד שמרגיש בלומדו תורת ה' כאלו אוכל וממלא בני מעיו ממזון טבעי:
@52 **עוד** אולי שנתכוון להודיע הקדמה תחת ששמעתיה משם הרב הקדוש מהר''י לוריא זצוק''ל (שער הגלגולים יט) והוא כי לפעמים יתהפך האדם וישתנה מטוב לרע בטבעו ומזגו ולא ידע מאיזה סיבה והוא עצמו יתמה איך נהפך בדעתו, ואמר כי זה יסובב לצד שלפעמים יאכל אדם מאכל שיש בו חלק מחלקי הרע או יש בו נפש רעה מהגלגולים לסיבת תחלואיהם וכאשר תכנס הנפש הרעה או ניצוץ הרע בקרבו תטהו מטוב לרע ותגבר בו בחינת הרע מעתה השומר עצמו ממאכלות הרעות יתגבר החפץ בו בדברים הנוגעים לנפש, והוא אומרו לעשות רצונך אלהי חפצתי וזה היה לי להיות תורתך בתוך מעי:
@52 **ולהשכילך** במשמעות אומרו ותורתך בתוך מעי. דע כי כל הצומח בין בדברים הכרחיים לחיות הנפש בין בדברים הסגוליים בעולם בין בדברים שהם תענוגי אדם שורש הכל והיוויו הוא מהתורה אשר היא אם הכל וכשם שבתורה פשט רמז דרש סוד כן מאכלים של עולם הזה, ועיין בפירוש שיר השירים (ראשון לציון פסוק הביאני אל בית היין) שחידשתי, וכשם שבעשבים יש דברים סגוליים וטבעיים כן יש בתורה מצות סגוליות וכו', והקדמה זו גדולה ויקרת הערך, וכתבתי ראשי פרקים להבינך אומרו ותורתך בתוך מעי כי כל האוכל אשר יאכל יסוד חיותו שבה נתהוה וגדל הוא מיניקת הקדושה שהיא התורה. ומעת פגם אדם הראשון ונתערב טוב ורע בכל אוכל תמצא חלק מהרע, ולזה צוה ה' על ערלת האילנות, ולזה גדל עם החטה מוץ ותבן וסובין הנזרקים, והבדילנו ה' מכמה דברים אשר שלט בהם חלק הרע לבל שקץ נפש הנבחרת, ולזה כשאדם אוכל דבר המותר כאילו נהנה מאור העליון ממאורי אור תורה אלא שנגשם לצד הצלחת יסודי ארץ שצריכים מזון כפי הכנתם והרכבתם, וזה אמר ותורתך בתוך מעי בזה גבר חפצו ותשוקתו לעשות רצונו יתברך כי אין רע בקרבו המסיר חפץ הערב לנפש:
@52 **נחזור** לענין שבאנו עליו כי בחינת החושב בדבר ערוה תגביר החפץ ותשליטנו ברצון ולא יושג הנצחון החפץ אלא דוקא באמצעות הרחקת הדבר מדעתו ומחשבתו לבל ראות הכיעור ולא יחשוב בו, אבל אם עיניו יביטו בדבר הנה הוא מסתכן, וכמעשה דוד המלך עליו השלום כשנסבב הדבר וראה מה שראה נתעורר לבו שהיה חלל ועשה מעשיו, ואפילו תחלת המחשבה בדבר זה תגרום תגבורת והולדת טבעיות החפץ ותגבורתו, ולזה נתכחם חכם החכמים שלמה המלך עליו השלום ואמר (משלי א) בני אם יפתוך חטאים פירוש בחינת החטא אל תאבה פירוש לא תכנם עם פתוייך בטוען ונטען, כי אריכות הרגשת החושב אפילו לבחינת השולל תפעיל הגברת החפץ ותהפך הרצון אליה. ומצות ה' ברה באה על הדבר בבחינת דיבור ואמירה, דיבור לומר גזירת מלך היא דבר מלך שלטון, אמירה לשון מענה רך ולשון רוממות לצד שהם ישגם במדריגה זו לאמר עליהם **אני ה' אלהיכם** ליחד שמו יתברך עליהם. גם מעלה גדולה היא לשומר בריתו, והיא ההדרגה שאין למעלה ממנה לזה אמר **ואמרת**:
@54 **את משפטי תעשו וגו'**. קשה אחר שאין מדבר אלא בפריצות העריות מה חוקים והמשפטים אשר צוה ה' אלהינו אותנו גם מה היא כוונתו באומרו **ללכת בהם**. גם צריך לדעת למה חזר פעם ב' לומר אני ה' אלהיכם:
@54 **ונראה** לפרש לפי מה שכתבתי בסמוך שהמחשבה בעריות תגדיל החפץ ותמעט מניעת הרצון, חש הכתוב שיאמר האדם להתרחק מכל וכל מפרט זה ויבטל מצות פריה ורביה ומצות היבום וכדומה ויהיה פרוש ממין זה לחלוטין שארז''ל (סוכה נב:) אבר קטן יש באדם משביעו רעב מרעיבו שבע, לזה צוה ה' ואמר **את משפטי תעשו** שהם ממין עצמו שאסרתי לך אני מחייבך לעשות, ואף על פי כן **את חקתי תשמרו** שהם העריות שאסר. או יאמר כי באמצעות שמירת העריות ימצאו הכנה בנפשותם לקיים מצות עשה כאומרו **משפטי תעשו** ושמירת כל הלאוין כאומרו **חקותי תשמר** ו, מה שאין כן אם יתעיב מעשיו בדרך ההוא תחלה נפשו בתחלואי הטומאה ולא יקיים אחת מהנה, כי טומאת חטא זה משרה טומאה על כל איברי האדם וכוחותיו, וכיון שכן כל הלאוין לא ימנע מהן כי בכל אבר טומאתו בו. וכן מצות עשה, והגם שיעשה לפעמים איזו מצוה אינה מצוה כי לא יתרצה בה הבורא יתברך שמו, על דרך אומרו (תהלים נ) ולרשע אמר אלהים מה לך לספר חוקי וגו', כי אין חפץ לה' בהם אלא במצוה הנעשית בקדושה. ואומרו **ללכת בהם** יכוין לומר לדרכנו כמין חומר, כי כאשר יהיה האדם טהור וקדוש מהתיעוב יוליד בטבעו לקיים המצות תמיד, על דרך אומרו (שם קיט) חשבתי דרכי ואשיבה רגלי אל עדותיך ודרז''ל (ויק''ר פל''ה) שרגליו של דוד מעצמם היו הולכות לבית המדרש לצד ההרגל והחפץ הנבחר, לזה אמר **ללכת בהם** פירוש שמעצמו ילך בהם בטבעו כעושה דברים שהטבע עושה לצד שעיקרו וגופו הכל עומד במקום טהור:
@54 **עוד** יכוין באומרו **ללכת בהם** על דרך מה שאמר הנביא (יחזקאל לג) צדקת הצדיק לא תזכר ביום שובו וגו', שאם יהיה צדיק כל ימיו וירשיע לבסוף הרי זה הפסיד זכותו ולא ילך עמו ביום לכתו לעולם העליון, לזה צוה ה' ואמר ללכת בהם פירוש שיתמיד במעשים הטובים ושמירות החוקים כדי שילך בהם ביום נסעו לדרך כל הארץ:
@54 **עוד** ירצה שלא יקוה האדם לשכר מצות בעולם הזה, על דרך אומרו היום לעשותם ולמחר לקבל שכרם (עירובין כב) שכל מה שיעשה לא יבחר לאכול עולמו בחייו אלא ילך לפניו צדקו לחזות בנועם ה':
@54 **עוד** ירצה על דרך אומרו כי נר מצוה ותורה אור, כי עולם העליון רחוק במהלך ובעלות נפש אדם מעולם זה לעולם העליון אם הוא רשע דרך רשעים באפילה, ובלכת אדם כשר מצות ותורה שבידו מאירים לו כאומרו (תהלים קיט) נר לרגלי דבריך ואור לנתיבתי, שהכוונה הוא להיות כי יש בנר מה שאין באור ויש באור מה שאין בנר, כי הנר יש בה בחינה גדולה מהאור כשיהיה קרוב ולזה אמרו רז''ל (פסחים ב) שבדיקת החמץ צריכה בלילה לאור הנר שהנר יפה לבדיקה להכניסה בחורין ובסדקין ומה שאין כן באור. ויש באור בחינה גדולה מהנר שרואה למרחוק מה שאין כן בנר, לזה אמר דוד כי מצות ה' יש באורם ב' בחינות הנזכרות, בחינת הנר בקרוב וזה אמר נר לרגלי שהוא בקרוב, ובחינת האור למרחוק והוא אומרו ואור לנתיבתי. וזה אמר כאן **ללכת בהם** פירוש באורם ילך שאם לא כן בחשיכה ילך ולא ידע במה יכשל רח''ל:
@54 **עוד** ירצה על דרך מה שאמר התנא האלהי רבי שמעון בר יוחאי ע''ה (זוהר ח''א קע:) כי רמ''ח אברי האדם ושס''ה גידיו הם כנגד מצות עשה ולא תעשה, ובעשות האדם מצוה באותו אבר שנעשית המצוה שורה בו שם הוי''ה יתברך, כי המצוה היא אותיות שם הויה חצים מגולה והוא סוד עלמא דאתגליא וחצים מכוסה סוד עלמא דאתכסיא כי אותיות מ''צ בא''ת ב''ש הם י''ה, ודבר ידוע הוא כי הקב''ה הוא שמו ושמו הוא בסוד אומרו (זכרי' יד) ה' אחד ושמו אחד. הראת לדעת כי בעשות המצוה נעשה האדם מרכבה לשכינה ומתהלך ה' בתוכו, וזה אמר **ללכת בהם**, וחזר ופירש מי הוא ההולך בהם ואמר **אני ה'** וכאלו אמר ללכת אני ה' בהם, והוא סוד (שמות כה ח) ושכנתי בתוכם. וכפי זה ירצה אומרו בהם כפשטה, כי בעשית המצוה נעשית ההכנה ללכת בה, וזהו סוד אומרו (כו יב) והתהלכתי בתוככם, (דברים ד ד) ואתם הדבקים בה' אלהיכם:
@55 **ושמרתם וגו'**. צריך לדעת למה כפל לומר דברים עצמם שאמר בסמוך, ויתבאר על פי דבריהם ז''ל (סנהדרין עד.) שאמרו וחי בהם ולא שימות בהם שאם אנסוהו לעבור על אחת ממצות ה' יעבור ולא יהרג. ואמרו עוד כי על ג' עבירות חייב אדם ליהרג ולא יעבור והם עבודה זרה גילוי עריות שפיכות דמים. מעתה אמר פסוק ראשון סמוך למצות עריות ולא התנה הכתוב אשר יעשה וגו' וחי בהם, ואמר פסוק ב' לצוות על שאר המצות ואמר **וחי בהם** לדייק ולומר שבמצות שנאמרו בפסוק שלפנינו שלא אמר וחי בהם יהרג ואל יעבור:
@55 **עוד** נראה בהעיר עוד למה שינה הכתוב בב' כתובים, בראשון אמר אני ה' אלהיכם, ובפסוק ב' אמר אני ה'. אכן כנגד ב' בנים דברה תורה אחד העושה מיראה ואחד העושה מאהבה, וכבר נתבארו הדברים במקומות אחרים (סוטה לא) כי העושה מיראה שכרו לאלף דור והעושה מאהבה שכרו כפול לאלפים. והנה מן הנמנע שישיג המשיג בחינת האהבה עד שתקדים לו בחינת היראה בסוד (תהלים קיח) זה השער לה', ואשר על כן אמר הכתוב כנגד בחינת היראה את משפטי וגו' **אני ה' אלהיכם**, דקדק להזכיר בחינת הדין שהוא רמוז בשם אלהים להעירך במי הכתוב מדבר, ואחר כך צוה לגדר ב' לעשות מאהבה, ולזה אמר **אני ה'** ולא הזכיר שם אלהות לומר שתהיה השמירה לצד אהבת הטוב והחפץ והרצון פעל בו לעשות מאמר קונו החביב מאהבתו אותו הגם שלא היה עונש לעובר. ואמר **וחי בהם** פירוש כי אדם שעושה מאהבה ישנו גם בטוב עולם הזה יתר על הגמול הקבוע לו בעולם הנצחי. ואולי כי לזה רמז באומרו וחי בתוספת וא''ו להעירך שזה נוסף על שכר אחר שהוא שכר הנעלם, מה שאין כן גדר הראשון שעושה מיראה שאין לו אלא לעולם העליון כאומרו ללכת בהם לעולם העליון, אבל גדר זה וחי בהם פירוש לא לעתיד לבד שאם כן היה לו לומר ויחיה אלא מעת טעמו טעם המצות בערך זה וחי בהם. ולדרך זה יתבאר גם כן מה שאמר בפרשת (עקב יא יד) והיה אם שמוע שאמר ונתתי מטר ארצכם וגו', פירוש לצד ששם נאמר לאהבה את ה' וגו' לזה הודיע כי מצוה זו יש לה שכר גם בעולם הזה וראוי הוא ליהנות בב' עולמות. והגם שאמרו ז''ל (קדושין לט:) שכר מצות בהאי עלמא ליכא, זה ישנו בהטבה זו, ורמז עולם העליון במה שאמר ונתתי בתוספ' וא''ו בתחילה יעוד השכר לו' אין זה אלא תוספת על הנעלם המושכל הנצחי:
@55 **האדם וגו'**. במסכת שבת וזה לשונם (ב''ק לח. ע''ז ג). אמר רבי יהודה מנין שאפילו גוי ועוסק בתורה שהוא ככהן גדול דכתיב אשר יעשה אותם האדם וחי וגו' כהנים לוים ישראלים לא נאמר אלא האדם ע''כ. פירוש לצד שהוקשה לרבי יהודה יתור האדם, עוד הוקשה לו למה דיבר הכתוב בלשון נסתר שהיה לו לומר אשר תעשו אותם כדרך שהתחיל לדבר ושמרתם וגו' לנוכח, ומכח זה דרש שנתכוון למי שלא היה שם באותו מצב שאינו לא כהן ולא לוי ולא ישראל ומי זה הוי אומר זה גוי. והתוספות ז''ל הקשו מברייתא (ב''מ קיד) שדרש ר''ש פסוק (יחזקאל לד) אדם אתם אתם קרויים אדם וכו'. ואמרו שיש לחלק בין אדם להאדם ע''כ. וכמו כן ראיתי בספר הזוהר (ח''א כה.) שחילוק זה אמיתי מצד עצמו, והוא דבר שב (ע) [מ] נין תלוי כידוע ליודעי חן שחשבון המעולה הוא של אדם ולא של האדם כי המוסיף גורע. ואולי כי כשעוסק הגוי בתורה גם עליו יהיה כתר זה ליקראות אדם, וכפי זה אות ה''א שבהאדם הוי ריבוי הגוי שגם הוא יקרא אדם כשעוסק בתורה, ואין אות הה''א כאן מעיקר השם והבן:
@74 **אל תטמאו בכל אלה**. אמרו ז''ל (תו''כ) בין בכולן בין במקצתן. פירוש אפילו במקצתו, וכאילו אמר אל תטמאו באחת מכל אלה. וצריך לדעת למה דיבר הכתוב בסדר זה שהיה לו לומר אל תטמאו באחת מכל אלה כדי שלא יהיה מקום לטעות. עוד קשה מה שגמר אומר כי בכל אלה נטמאו הגוים והגוים אין לנו מקום לומר שלא נטמאו אלא באחת שהשטוף בזמה ידו בכל. גם משמעות בכל אלה נטמאו, יגיד שבכולן נטמאו ומעתה מה טעם נשמע אל הדבר אשר יצוה עליו שהכונה היא אל תטמאו בכולן:
@74 **ונראה** לפרש בהשכיל על דבר אמת למה לא גילה ה' בתורה הדרגות המצות וסגולתם, ואדרבה בא שלמה המלך עליו השלום ואמר (משלי ה) אורח חיים פן תפלם וענו אחריו רז''ל (אבות פ''ב מ''א) שאין לנו לומר מצוה זו גדולה וזו קטנה שאין אתה יודע וכו', והוכיחו (דב''ר פ''ו ירושלמי פאה פ''א ה''א) ממה שקבע ה' שכר שוה לגדולה שבגדולות עם קטנה שבקטנות, ועל כולן אני דן שהסברא נותנת שיש מצות ודאי גדולות ביותר ולמה סתם ה' הדבר:
@74 **ונראה** כי לצד שיש צורך במצות הקטנות כבגדולות שכל מצוה ומצוה סגולתה בפני עצמה, ומה בכך אם שכרה מעט כיון ששכרה הוי דבר שאינו בנמצא כשכר הגדולה, וכל המצות צריכין לתיקוני הנפש, לזה צוה ה' קטן וגדול בהדרגה אחת כדי שיעשו ישראל כולם כאחד. והוא מאמר שלמה (קהלת ט) כל אשר תמצא ידך לעשות בכחך עשה:
@74 **עוד** נראה טעם אחר כי לצד שיש מצות שסגולתם להאריך ימים בעולם הזה, ויש שסגולתם עושר, ויש שסגולתם בנים, וכן על זה הדרך וחש ה' כשיתגלה הדבר כל אחד ילך וישתדל במה שחפץ ובמה שצריך ולא ישתדלו בשאר מצות כמצטרך, לזה סתם הדברים ובזה ישתדל האדם בכולן כדי שתבוא לידו גם מצוה שסגולתה דבר הצריך לו, ובזה יש טעם למה שאנו רואים כמה בני אדם רעים לשמים ולבריות ובתיהם שלום מפחד מלאים כל טוב, כי אפשר שבא לידם מצוה שסגולתה הצלחת עולם הזה, ואין העבירות שעושים מונעים סגולת המצוה והצלחתה, וכל זה בבחינת מצות עשה, ובמצות לא תעשה יהיה הדבר כן, יש עבירות שפורענותם לעולם הבא, ויש שפורענותם יסורין באריכות הזמן, ויש שפורענתם ברחמנות, ויש כ''כ אכזריות, והלא תמצא כמה רשעים שעברו על הכריתות ולא נכרתו הגם שעמדו בתוקף הרשע עד שעברו זמן הכריתה, אלא ודאי שיש שמשתלם עליה בעולם הזה ויש שמשתלם עליה לעולם הבא. ודבר ידוע הוא שיותר יפעיל הפחד בלב בני אדם מוסר המשתלם בעולם הזה להיותו נגלה מעונש הנסתר:
@74 **וכבר** קדם לנו כי ה' ב''ה יקפיד אפילו על ברואיו הקרובים אליו לבל ידברו דבר שאינו על קו הצדק, ואפילו דברים שנראם כשקר, וצא ולמד מאמר רבי עקיבא לחבריו (חגיגה יד:) כשתגיעו לאבני שיש טהור אל תאמרו מים מים, ומכאן נקיש לכסף נבחר לשון צדיק הוא ה' אלהינו מקור האמת כי יקפיד לבל יכתוב בתורה אלא דברים המובהקים במדת אמת:
@74 **ובזה** נבא אל הביאור, והוא כי לצד שעונש זה של הקאת הארץ יושביה אינו אלא על פרט אחד מהתועבות האמורים בפרשה כאשר אבאר בסמוך אבל שאר התועבות יש להם עונש אחר כאשר שפט אל חי תמים דעים כפי בחינת התיעוב, ולזה כשבא לצוות את עמו רצה להודיעם כי יש בתועבות אשר הזהירם עליהם תיעוב אחד אשר יסובב שתקיא אותם הארץ, ולא רצה ה' לגלותו כדי שלפחדו ישמרו עצמם מכולם יחד כמו שכתבתי שיותר ירעיד עונש הנגלה מעונש הנסתר, וזה שיעור הדברים **אל תטמאו בכל אלה**. פירוש, באחד מכל אלה.
@74 **כי בכל אלה נטמאו הגוים אשר אני משלח מפניכם ותטמא הארץ ואפקוד עונה**. פירוש, אחד הוא הגורם ואותו פקדתי על העיר ותקיא את יושביה הא למדת שעל עון אחד קאה הארץ אותם, אם כן תתחייב לומר כי מאמר **אל תטמאו בכל אלה** הוא באחד מכל אלה כיון שעל אחד היה העונש ואין אתה יודע מי הוא. ואמר עוד **ושמרתם** וגו' **ולא תעשו מכל התועבות** וגו' כי את כל וגו' עשו, נתכוון הכתוב בזה להודיעם שכל התועבות עשו אנשי הארץ ואין אחת בכל התועבות שלא עשו אותם, והמכוון בזה כדי שיכנסו כולן בגדר המיחוש, כי כל שלא עשו אותה אנשי הארץ אין בה פחד ההקאה מן הארץ, לזה הוצרך לומר כי כל וגו'. ודבר זה דומה לכלי מים שהקיא בו נחש כל הכלים שיכנסו בגדר ספק כלי זה אדם נרעד מגשת אליו, וכמו כן הדבר הזה. והגם שהעון הגורם הקאה הוא אחד ותועבות אשר יצוה רבים הם. דבר זה דין קבוע יש לו שאדם הוא פושט עצמו להתעיב, ודין לוקח יש לו ולא דין פורש, וכמו שהארכתי בזה בחיבורי על יורה דעה (פ''ת סי' קי) וכיון שכן כל הקבוע כמחצה ומחצה. ואחר שהפחידם בעונש נגלה חזר ואמר **כי כל אשר יעשה** וגו' פירוש שגם על כל שאר התועבות יש עונש חמור להכרתת הנפש אלא שאחת מהם גורמת עונש הנגלה:
@75 **ותטמא הארץ וגו'**. הכוונה הוא על דרך מה שאז''ל (זוהר ח''ג נג:) כי במעשה ישראל יתהו' הרוחניות אם לטוב אם לרע, והוא אומרם (אבות פ''ד מי''א) העושה מצוה אחת וכו' והעובר עבירה אחת, וזהו שרמז כאן באומרו **ואפקוד עונה עליה**, על דרך אומרו (ירמיה ב) תיסרך רעתך, כי מפעולת הרע יתהוה הקטיגור אשר ישלם לאיש כמעשהו. ואז''ל (תומר דבורה פ''א) כי תשלום הדין הוא כל מלאך מחבל שנברא מכל עבירה בא ומשתלם מעושהו עד שכלה באמצעות פעולת היסורין כי הוא מתמעט והולך וכשכלה כח פועל הרע הוא נאבד, ושפט ה' דבר זה בצדק כדי שישתלם כל אחד כפי מעשיו בכיוון מופלא, כי כפי כח הנעשה במעשה הרע יהיה בנברא, והוא מאמר הכתוב כאן באומר **ואפקוד עונה** פירוש לשון מינוי שממנה העון עצמו על עושהו. ואומרו לשון יחיד כבר פירשתי למעלה. עוד נראה לומר כפי דרכנו שאפשר שאין הקטיגורים משתלמים יחד אלא בזה אחר זה, לזה אמר לשון יחיד, וזה דרך דרש:
@76 **ושמרתם אתם**. טעם אומרו תיבת **אתם** ולא הספיק במה שדיבר להם לנוכח ושמרתם נראה כי מצוה זו באה להזהיר על החוקים והמשפטים שלא יהיו מתבטלים מכל המצטוים עליהם, והכוונה שלא יאמר אדם שאין לו להקפיד אלא שלא יתבטלו המצות על ידו אבל אם יתבטלו מהזולת אין לו לחוש, לזה אמר **ושמרתם את חוקותי** וגו' פירוש שלא יתבטלו מכל המצטוים עליהם. ולצד כי מצוה זו אינה אלא על הגדולים לזה אמר אתם דבר לנכח עם משה ובית דינו, כי על בתי דיני ישראל לפקוח עין לבל תתבטל מצוה אחת ממצות התורה מבני ברית. ובתורת כהנים אמרו ז''ל ושמרתם אתם אתם נאים שומרים אותם שאתם פתחתם אותם, וכן הוא (שה''ש) אומר גן נעול אחותי כלה גל נעול מעין חתום ע''כ פירוש כאן קרב ה' אזהרת העריות אל טבע הרגיל, ואמר להם כי מצוה זו של שמירת העריות אינו דבר חדש וזר בערך ישראל שהרי הם מצד עצמם קודם שנצטוו היו פרושים מן העריות דכתיב גן נעול אחותי כלה, והוא מה שרמז באומרו **אתם** פירוש מה שאתם שמרתם כבר מעצמיכם:
@76 **האזרח והגר**. רז''ל דרשו (תו''כ) אזרח זה אזרח האזרח לרבות נשי אזרחים, גר זה הגר, הגר לרבות נשי הגרים וכו' ע''כ, טעם שהוצרך הכתוב לפרט כל פרטים אלו, לבל תטעו מתיבת אתם ותאמר שבא למעט איזה פרט מהפרטים הרשומים תלמוד לומר וכו':
@76 **עוד** נראה כי נתכוין הכתוב להודיע שאם ישראל והגרים ישמרו כל החוקים והמשפטים אין כח במעשה הגוים הגם שיתעבו מעשיהם להקיא הארץ יושביה, ודוקא קודם שנכנסו ישראל לארץ הוא שקאה הארץ הגוים על מעשה התיעוב אבל אחר כניסת ישראל לארץ אין הדבר תלוי אלא בישראל והגר, ולזה פרט אותם שמעשיהם יסובבו למעט הגוים:
@76 **ותמצא** שאמר הכתוב (שמות כג לג) לא ישבו בארצך פן יחטיאו אותך לי, וכתב רמב''ם וסמ''ק שגוי שלא קבל עליו ז' מצות אסור לדור בארץ ישראל מטעם פן יחטיאו וגו', הא למדת שאם לא היה טעם פן יחטיאו הגם שלא יקבל עליו ז' מצות ויתעב מעשיו אין לחוש להקאת הארץ בשבילם:
@78 **ולא תקיא וגו' כאשר קאה וגו** '. לא הספיק מה שאמר למעלה ותקיא הארץ, לזרז ביותר על דרך מה שדרש רבי אליעזר בן עזריה בפרשת אחרי מות (בתו''כ) משל לחולה שנכנס אצלו הרופא וכו' אל תאכל צונן וכו' שלא תמות כדרך שמת פלוני זה זרזו יותר וכו' עד כאן, כמו כן במה שלפנינו נתכוין ה' לזרז ישראל ביותר:
@80 **ושמרתם את משמרתי**. יצו ה' על הגדרים השומרים לבלתי יבא להכשל בתיעוב, והוא אומרו **ושמרתם את משמרתי** פירוש משמרת הגדר, והטעם לבלתי עשות וגו' אפילו בשוגג, והגם שלא תתחייב על התיעוב בשוגג ואף על פי כן אתם מתטמאים במעשה התיעוב, והוא אומרו **ולא תטמאו בהם**, ולחשש זה. תשמרו משמרתי. ואומרו **אני ה' אלהיכם**, נתכוון לומר כי בהטמאם אפילו בשוגג הם נגרעים מערך זה שיתייחד שמו יתברך עליהם, כי התיעוב בכל מציאות שיהיה יפעיל פירוד בין ישראל ובין השכינה, שאין שכינה שורה אלא על המושלל מהכיעור ההוא וקדוש יאמר לו כל הכתוב לחיים:
@80 **חסלת פרשת אחרי**
